VALUES ('ford', 'bronco', 'cargo-space', $s$Ford$s$, $s$Bronco$s$, $s$Cargo space$s$, $s$Ford Bronco Cargo Space: 2-Door and 4-Door in Cubic Feet$s$, $s$Ford Bronco Cargo Space: 2-Door vs 4-Door (cu ft)$s$, $s$Ford Bronco cargo space from Ford's 2026 spec sheet: 20.6 cu ft behind the rear seat in the 2-door, 35.6 to 38.3 cu ft in the 4-door.$s$, $s$[{"q": "How much cargo space does a 4-door Bronco have?", "a": "35.6 cu ft behind the second row with the hard top and 38.3 cu ft with the soft top; 77.6 and 83.0 cu ft behind the first row, by Ford's 2026 sheet."}, {"q": "How much cargo space does a 2-door Bronco have?", "a": "20.6 cu ft behind the second row and 52.0 cu ft behind the first row, with the hard top."}, {"q": "Why does the soft top have more space?", "a": "Ford's sheet lists higher volumes for the 4-door soft top than for the hard top. It does not give the reason."}, {"q": "How big is the Bronco's fuel tank?", "a": "16.9 gallons in the 2-door and 20.8 gallons in the 4-door."}]$s$::jsonb, $s${"answer": "The 2026 Ford Bronco 4-door has 35.6 cu ft of cargo space behind the second row with the hard top (38.3 cu ft with the soft top) and 77.6 cu ft behind the first row (83.0 cu ft with the soft top). The 2-door has 20.6 cu ft behind the second row and 52.0 cu ft behind the first.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "2021 to 2025: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "cargo", "h": "Bronco cargo volume (2026)", "table": {"head": ["Measurement", "2-door, hard top", "4-door, hard top", "4-door, soft top"], "rows": [["Behind the second row", "20.6 cu ft", "35.6 cu ft", "38.3 cu ft", 1], ["Behind the first row", "52.0 cu ft", "77.6 cu ft", "83.0 cu ft", 1]]}, "notes": ["Ford prints a second figure of 72.9 cu ft behind the first row, marked Raptor."]}, {"id": "size", "h": "Length, wheelbase and fuel tank (2026)", "table": {"head": ["Measurement", "2-door Base", "4-door Base"], "rows": [["Overall length", "173.7 in", "189.4 in", 1], ["Wheelbase", "100.4 in", "116.1 in", 1], ["Fuel tank", "16.9 gal", "20.8 gal", 1]]}}], "check": ["Volume figures do not tell you whether one large item fits: measure the opening and the floor of your own truck.", "Cargo on the roof or on a hitch rack counts against payload the same way as cargo inside.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["roof-racks", "cargo-boxes", "floor-mats"], "sources": [["Ford, 2026 Bronco Technical Specifications (v1.0, 18 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Bronco_Technical_Specifications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
