  published_at=COALESCE(spec_pages.published_at, EXCLUDED.published_at), updated_at=now();

INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'bronco', 'tire-size', $s$Ford$s$, $s$Bronco$s$, $s$Tire size$s$, $s$Ford Bronco Tire Size by Trim: 30 to 37 Inch (2026)$s$, $s$Ford Bronco Tire Size by Trim: 30 to 37 Inch (2026)$s$, $s$Ford Bronco tire sizes from Ford's 2026 spec sheet: 30-inch on Base, 32-inch on Big Bend and Outer Banks, 33-inch on Badlands, 37-inch on Raptor.$s$, $s$[{"q": "What size tires come on a 2026 Ford Bronco?", "a": "Ford lists tires by outer diameter: 30 inches on the Base, 32 inches on the Big Bend and Outer Banks, 33 inches on the Badlands, 35 inches on the Stroppe and Heritage Editions and 37 inches on the Raptor."}, {"q": "What tires come with the Sasquatch Package?", "a": "35-inch tires on 17.0 x 8.5 beadlock-capable wheels. Ford lists the Sasquatch Package for the Base, Big Bend, Outer Banks and Badlands."}, {"q": "Which Bronco wheels are beadlock capable?", "a": "By Ford's 2026 sheet, the 17.0 x 8.5 wheels that carry the 35-inch and 37-inch tires."}, {"q": "What is the exact tire size code?", "a": "Ford's tire table gives the outer diameter and wheel size, not a code such as 285/70R17. The code for your Bronco is on the tire sidewall and on the door-jamb label."}]$s$::jsonb, $s${"answer": "The 2026 Ford Bronco comes with tires from 30 to 37 inches in outer diameter: 30-inch on the Base, 32-inch on the Big Bend and Outer Banks, 33-inch on the Badlands, 35-inch on the Stroppe and Heritage Editions or with the Sasquatch Package, and 37-inch on the Raptor.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "2021 to 2025, metric tire size codes, tread type and tire pressures: Ford's 2026 table prints outer diameter and wheel size only, and its tread-type row could not be matched to columns.", "sections": [{"id": "tires", "h": "Tire diameter and wheel size by trim (2026)", "table": {"head": ["Tire outer diameter", "Wheel size", "Beadlock capable", "Trim level", "Optional package"], "rows": [["30 in", "16.0 x 7.0", "—", "Base", "—", 1], ["32 in", "17.0 x 7.5", "—", "Big Bend (std.)", "—", 1], ["32 in", "17.0 x 7.5", "—", "Big Bend (opt.)", "Black Diamond, Free Wheeling", 1], ["32 in", "18.0 x 7.5", "—", "Outer Banks", "—", 1], ["33 in", "17.0 x 8.0", "—", "Badlands", "—", 1], ["35 in", "17.0 x 8.5", "Yes", "Stroppe Edition, Heritage Edition", "Sasquatch on Base, Big Bend, Outer Banks, Badlands", 1], ["37 in", "17.0 x 8.5", "Yes", "Raptor", "—", 1]]}, "notes": ["The rows follow the seven columns of Ford's table. Wheel sizes are diameter x width in inches. A dash means Ford's table shows a dash in that cell."]}], "check": ["Read the size code molded into the tire sidewall: it gives the exact metric size that Ford's table does not.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure for your Bronco.", "Check whether your Bronco has the Sasquatch Package on the window sticker before you order tires or wheels.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "roof-racks"], "sources": [["Ford, 2026 Bronco Technical Specifications (v1.0, 18 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Bronco_Technical_Specifications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
