INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'bronco', 'towing-capacity', $s$Ford$s$, $s$Bronco$s$, $s$Towing capacity$s$, $s$Ford Bronco Towing Capacity: 3,500 lb, or 4,500 lb for the Raptor$s$, $s$Ford Bronco Towing Capacity (2-Door, 4-Door, Raptor)$s$, $s$Ford Bronco towing capacity from Ford's 2026 spec sheet: 3,500 lb for 2-door and 4-door models, 4,500 lb for the Raptor, with payload figures.$s$, $s$[{"q": "How much can a Ford Bronco tow?", "a": "3,500 lb for nearly every 2026 Bronco, 2-door or 4-door, by Ford's specification sheet. The Raptor is rated at 4,500 lb."}, {"q": "Does the 2.7L V6 tow more than the 2.3L?", "a": "No. Ford lists 3,500 lb for both engines. One build is slightly lower: the 4-door Badlands with the 2.7L V6, at 3,460 lb."}, {"q": "Does the 2-door Bronco tow less than the 4-door?", "a": "Not in Ford's 2026 sheet: both are listed at 3,500 lb."}, {"q": "Do I need a tow package?", "a": "Ford's sheet says the Trailer Tow Prep Package is included on all models except the Raptor. Check your own truck's equipment and manual before towing."}]$s$::jsonb, $s${"answer": "The 2026 Ford Bronco tows 3,500 lb in 2-door and 4-door form with either the 2.3L or the 2.7L engine. The Bronco Raptor tows 4,500 lb. One build is listed slightly lower: the 4-door Badlands with the 2.7L V6, at 3,460 lb.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "2021 to 2025: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "towing", "h": "Bronco maximum trailer tow (2026)", "table": {"head": ["Model", "Engine", "Maximum trailer tow"], "rows": [["2-door, all listed trims", "2.3L I-4", "3,500 lb", 1], ["4-door, all listed trims", "2.3L I-4", "3,500 lb", 1], ["4-door Outer Banks, Heritage Edition, Stroppe Edition", "2.7L V6", "3,500 lb", 1], ["4-door Badlands", "2.7L V6", "3,460 lb", 1], ["Raptor (4-door)", "3.0L V6", "4,500 lb", 1]]}, "notes": ["Ford's footnote: maximum towing is for properly equipped vehicles with required equipment and a 150 lb driver and passenger."]}, {"id": "payload", "h": "Payload of common builds (2026, automatic transmission)", "intro": "Tongue weight counts against payload, so the two figures belong together. Ford lists payload for every build; these are the base and the heaviest-equipped ones.", "table": {"head": ["Model", "Engine", "Maximum payload"], "rows": [["2-door Base", "2.3L I-4", "1,188 lb", 1], ["2-door Badlands", "2.3L I-4", "1,067 lb", 1], ["4-door Base", "2.3L I-4", "1,395 lb", 1], ["4-door Outer Banks", "2.7L V6", "1,296 lb", 1], ["4-door Badlands", "2.7L V6", "1,204 lb", 1], ["Raptor (4-door)", "3.0L V6", "1,155 lb", 1]]}}], "check": ["Read the payload on the yellow label on the driver's door jamb. A hard top, bumpers, a winch and bigger tires all take from it.", "Tongue weight is normally about a tenth of the trailer's weight, and it counts as payload.", "Check the hitch receiver's own rating: use the lower of the receiver's and the vehicle's figure.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "bike-racks", "roof-racks"], "sources": [["Ford, 2026 Bronco Technical Specifications (v1.0, 18 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Bronco_Technical_Specifications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
