INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'expedition', 'gas-tank-size', $s$Ford$s$, $s$Expedition$s$, $s$Gas tank size$s$, $s$Ford Expedition Gas Tank Size: Expedition and MAX (2026)$s$, $s$Ford Expedition Gas Tank Size: Expedition vs MAX (2026)$s$, $s$Ford Expedition gas tank size from Ford's 2026 spec sheet: 23.6 gallons on the Expedition and 27.8 gallons on the Expedition MAX.$s$, $s$[{"q": "How many gallons does a Ford Expedition hold?", "a": "23.6 gallons, by Ford's 2026 specification sheet."}, {"q": "How big is the Expedition MAX gas tank?", "a": "27.8 gallons, by the same sheet."}, {"q": "Does the High-Output engine have a different tank?", "a": "No. Ford prints the same two figures, 23.6 gallons for the Expedition and 27.8 gallons for the Expedition MAX, under both the 3.5L EcoBoost V6 and the 3.5L EcoBoost V6 High-Output."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition holds 23.6 gallons of fuel and the Expedition MAX holds 27.8 gallons, according to Ford's specification sheet. The figures are the same for both versions of the 3.5L EcoBoost V6.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "Earlier model years: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "tank", "h": "Fuel capacity by body (2026)", "table": {"head": ["Body", "Fuel capacity"], "rows": [["Expedition", "23.6 gal", 1], ["Expedition MAX", "27.8 gal", 1]]}, "notes": ["Ford prints this row in its engine table, with the same values under the 3.5L EcoBoost V6 and the 3.5L EcoBoost V6 High-Output."]}], "check": ["Check whether you have an Expedition or the longer Expedition MAX: the name is on the window sticker.", "The pump may stop before or after the listed figure: the capacity is the tank's rated volume, not what fits after the low-fuel light.", "For towing range, expect far fewer miles per tank than the window-sticker fuel economy suggests.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "roof-racks", "cargo-boxes"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
