INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'expedition', 'ground-clearance', $s$Ford$s$, $s$Expedition$s$, $s$Ground clearance$s$, $s$Ford Expedition Ground Clearance: MAX and Tremor (2026)$s$, $s$Ford Expedition Ground Clearance: MAX and Tremor (2026)$s$, $s$Ford Expedition ground clearance from Ford's 2026 spec sheet: 8.7 in on Expedition, 8.7 to 8.8 in on Expedition MAX and 10.6 in on Tremor.$s$, $s$[{"q": "What is the ground clearance of a 2026 Ford Expedition?", "a": "8.7 inches with either 4x2 or 4x4, by Ford's 2026 specification sheet."}, {"q": "How much ground clearance does the Expedition MAX have?", "a": "Ford lists 8.8 inches for the MAX 4x2 and 8.7 inches for the MAX 4x4."}, {"q": "How much ground clearance does the Expedition Tremor have?", "a": "10.6 inches, with a 28.2° approach angle, a 22.4° ramp breakover angle and a 24.3° departure angle."}, {"q": "Does a loaded Expedition sit lower?", "a": "Yes. Ford's figure is for the vehicle as built; passengers, cargo and a trailer on the hitch all lower the real clearance."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition has 8.7 inches of ground clearance, the Expedition MAX 8.8 inches (4x2) or 8.7 inches (4x4), and the Expedition Tremor 10.6 inches, according to Ford's specification sheet.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "Earlier model years. Ford's sheet gives one figure per body and drivetrain; it does not break it down by trim, wheel size or suspension option apart from Tremor.", "sections": [{"id": "clearance", "h": "Ground clearance and angles (2026)", "table": {"head": ["Configuration", "Ground clearance", "Approach angle", "Ramp breakover angle", "Departure angle"], "rows": [["Expedition, 4x2", "8.7 in", "21.1°", "19.3°", "23.5°", 1], ["Expedition, 4x4", "8.7 in", "21.1°", "19.1°", "23.5°", 1], ["Expedition MAX, 4x2", "8.8 in", "21.5°", "18.3°", "22.3°", 1], ["Expedition MAX, 4x4", "8.7 in", "21.2°", "17.3°", "22.3°", 1], ["Expedition Tremor, 4x4", "10.6 in", "28.2°", "22.4°", "24.3°", 1]]}, "notes": ["Ford's table has no footnote on these rows."]}], "check": ["Find the body (Expedition or Expedition MAX), trim and drivetrain on your window sticker, then read the matching row.", "Running boards and a hitch can sit lower than the listed clearance point; measure them if you drive on rutted tracks.", "To measure your own vehicle, park on level ground and measure from the ground to the lowest fixed point underneath.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["running-boards", "hitches", "roof-racks"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
