VALUES ('ford', 'expedition', 'oil-type-capacity', $s$Ford$s$, $s$Expedition$s$, $s$Oil capacity$s$, $s$Ford Expedition Oil Capacity (2026)$s$, $s$Ford Expedition Oil Capacity: 3.5L EcoBoost (2026)$s$, $s$Ford Expedition engine oil capacity from Ford's 2026 spec sheet: 6.0 quarts with the oil filter, for both versions of the 3.5L EcoBoost V6.$s$, $s$[{"q": "How much oil does a 2026 Ford Expedition take?", "a": "6.0 quarts with the oil filter, by Ford's 2026 specification sheet."}, {"q": "Does the High-Output engine take more oil?", "a": "No. Ford prints 6.0 quarts with the oil filter under both the 3.5L EcoBoost V6 and the 3.5L EcoBoost V6 High-Output."}, {"q": "What type of oil does the Expedition use?", "a": "Ford's specification sheet gives capacity only. The oil grade and specification are in the capacities and specifications section of the owner's manual, and the grade is usually printed on the oil filler cap."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition takes 6.0 quarts of engine oil with the oil filter, according to Ford's specification sheet. The figure is the same for the 3.5L EcoBoost V6 and the High-Output version. The sheet does not print the oil grade.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "The oil grade (viscosity and specification) for any year, and capacities for earlier model years: Ford's 2026 sheet prints capacity only.", "sections": [{"id": "oil", "h": "Engine oil capacity (2026)", "table": {"head": ["Engine", "Oil capacity"], "rows": [["3.5L EcoBoost V6", "6.0 qt (with oil filter)", 1], ["3.5L EcoBoost V6 High-Output", "6.0 qt (with oil filter)", 1]]}}], "check": ["Look up the oil grade and specification in the capacities and specifications section of your owner's manual before you buy oil.", "After an oil change, fill short of the listed capacity, run the engine briefly, wait, then top up to the upper mark on the dipstick.", "The Expedition and Expedition MAX share these engines, so the figure does not depend on body length.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["floor-mats", "seat-covers"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
