INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'expedition', 'tire-size', $s$Ford$s$, $s$Expedition$s$, $s$Tire size$s$, $s$Ford Expedition Tire Size by Trim (2026)$s$, $s$Ford Expedition Tire Size by Trim (2026)$s$, $s$Ford Expedition tire sizes from Ford's 2026 spec sheet: 265/70R18 on Active, 275/70R18 on Tremor, 275/60R20 on Platinum, 275/50R22 on King Ranch.$s$, $s$[{"q": "What size tires are on a 2026 Ford Expedition?", "a": "Ford lists 265/70R18 all-terrain for the Active, 275/70R18 all-terrain for the Tremor, 275/60R20 all-season for the Platinum and 275/50R22 all-season for the King Ranch."}, {"q": "Which Expedition has 24-inch tires?", "a": "Ford lists 285/40R24 all-season tires with the Stealth Performance Package on the Platinum and with the Platinum Ultimate Package."}, {"q": "What tires come on the 20-inch Active wheels?", "a": "275/60R20: all-season on the 4x2 Active and all-terrain on the 4x4 Active, with the 20-inch Carbonized Gray bright-machined aluminum wheels."}, {"q": "Does the Expedition MAX use different tires?", "a": "Ford's sheet lists tires by trim and package and does not give a separate list for the Expedition MAX."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition uses 265/70R18 tires on the Active, 275/70R18 on the Tremor, 275/60R20 on the Platinum and 275/50R22 on the King Ranch, with 22-inch and 24-inch sizes in Platinum packages, according to Ford's specification sheet.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "Earlier model years, tire pressures and load ratings. Ford's sheet splits the list into standard and optional columns, but the two readings did not agree on the column of each entry, so that split is left out.", "sections": [{"id": "tires", "h": "Tire sizes by trim and package (2026)", "table": {"head": ["Tire", "Ford lists it for"], "rows": [["265/70R18 all-terrain", "Active 200A/202A", 1], ["275/70R18 all-terrain", "Tremor", 1], ["275/60R20 all-season", "Platinum", 1], ["275/50R22 all-season", "King Ranch", 1], ["275/60R20 all-season", "4x2 Active 200A/202A with 20\" Carbonized Gray bright-machined aluminum wheels", 1], ["275/60R20 all-terrain", "4x4 Active 200A/202A with 20\" Carbonized Gray bright-machined aluminum wheels", 1], ["275/50R22 all-season", "Included in Driver's Package with 22\" Ebony bright machined-face aluminum wheels on Platinum", 1], ["275/50R22 all-season", "Included in Stealth Appearance Package with 22\" Magnetite-painted aluminum wheels on Platinum", 1], ["285/40R24 all-season", "Included in Stealth Performance Package with 24\" Ebony-painted aluminum wheels on Platinum", 1], ["285/40R24 all-season", "Included in Platinum Ultimate Package with 24\" Tarnished Dark Metallic bright machined-face aluminum wheels", 1]]}}], "check": ["Read the size molded into the sidewall of the tires on your vehicle: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["running-boards", "floor-mats", "roof-racks"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
