INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'expedition', 'towing-capacity', $s$Ford$s$, $s$Expedition$s$, $s$Towing capacity$s$, $s$Ford Expedition Towing Capacity: Expedition, MAX and Tremor$s$, $s$Ford Expedition Towing Capacity (Expedition and MAX)$s$, $s$Ford Expedition towing capacity from Ford's 2026 spec sheet: up to 9,600 lb for the 4x4, 6,000 lb for the 4x2, 9,000 lb for the MAX 4x4.$s$, $s$[{"q": "How much can a Ford Expedition tow?", "a": "Up to 9,600 lb for 2026: an Expedition 4x4 without the 24 in wheels. Ford's sheet lists 6,000 lb for the 4x2."}, {"q": "How much can an Expedition MAX tow?", "a": "6,300 lb with 4x2 and up to 9,000 lb with 4x4 without the 24 in wheels."}, {"q": "How much can the Expedition Tremor tow?", "a": "Up to 9,300 lb, by Ford's 2026 sheet."}, {"q": "Do I need a weight distributing hitch?", "a": "Ford states that trailer weights over 7,000 lb require a weight distributing hitch on the Expedition and Expedition MAX."}, {"q": "Do the 24 in wheels lower the rating?", "a": "Yes. Ford lists 9,200 lb for the Expedition 4x4 with 24 in wheels against 9,600 lb without them."}]$s$::jsonb, $s${"answer": "The 2026 Ford Expedition tows up to 9,600 lb as a 4x4 without the 24 in wheels and 6,000 lb as a 4x2. The Expedition MAX is rated at 6,300 lb (4x2) and up to 9,000 lb (4x4), and the Tremor at up to 9,300 lb. Above 7,000 lb Ford requires a weight distributing hitch.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "Earlier model years are not on this page yet.", "sections": [{"id": "towing", "h": "Expedition maximum towing (2026)", "intro": "All figures are with the 3.5L EcoBoost V6; the Tremor and the Platinum figure are with the High-Output version.", "table": {"head": ["Model", "Drive", "Maximum towing", "Ford's condition"], "rows": [["Expedition", "4x2", "6,000 lb", "When properly equipped", 1], ["Expedition", "4x4", "9,600 lb", "Without 24 in wheels; weight distributing hitch", 1], ["Expedition", "4x4", "9,200 lb", "With 24 in wheels; weight distributing hitch", 1], ["Expedition Platinum (High-Output)", "4x4", "9,200 lb", "With 24 in wheels; weight distributing hitch", 1], ["Expedition Tremor (High-Output)", "4x4", "9,300 lb", "Weight distributing hitch", 1], ["Expedition MAX", "4x2", "6,300 lb", "When properly equipped", 1], ["Expedition MAX", "4x4", "9,000 lb", "Without 24 in wheels; weight distributing hitch", 1]]}, "notes": ["Ford's footnote: maximum loaded trailer weight ratings over 7,000 lb require a weight distributing hitch for Expedition and Expedition MAX models."]}, {"id": "gcwr", "h": "Minimum gross combination weight rating (2026)", "intro": "The GCWR is the limit for the loaded vehicle and loaded trailer together.", "table": {"head": ["Model", "Drive", "Minimum GCWR"], "rows": [["Expedition", "4x2", "12,000 lb", 1], ["Expedition", "4x4", "15,900 lb", 1], ["Expedition MAX", "4x2", "12,500 lb", 1], ["Expedition MAX", "4x4", "15,600 lb", 1], ["Expedition Tremor", "4x4", "15,600 lb", 1]]}}], "check": ["Check your wheel size: the 24 in wheels carry the lower rating.", "Over 7,000 lb, use a weight distributing hitch rated for the trailer.", "Weigh the loaded vehicle and trailer together and compare with the GCWR in your owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "running-boards", "roof-racks"], "sources": [["Ford, 2026 Expedition Technical Specifications (v1.0, 5 Feb 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Expedition_Technical_Specfications.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
