  published_at=COALESCE(spec_pages.published_at, EXCLUDED.published_at), updated_at=now();

INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'bed-dimensions', $s$Ford$s$, $s$F-150$s$, $s$Bed size$s$, $s$Ford F-150 Bed Size: 5.5 ft, 6.5 ft and 8 ft Box Dimensions$s$, $s$Ford F-150 Bed Size: 5.5, 6.5 and 8 ft Dimensions$s$, $s$Ford F-150 bed size from Ford's 2026 spec sheet: 67.1, 78.9 or 97.6 in long, 50.6 in between the wheelhouses, 21.4 in deep, by box.$s$, $s$[{"q": "How long is the F-150 5.5 ft bed?", "a": "67.1 in at the floor (67.2 in on the Raptor), by Ford's 2026 specification sheet."}, {"q": "How long is the F-150 6.5 ft bed?", "a": "78.9 in at the floor."}, {"q": "How wide is an F-150 bed between the wheel wells?", "a": "50.6 in on all three boxes, so a 48 in sheet lies flat between the wheelhouses."}, {"q": "Which cab comes with which bed?", "a": "For 2026 Ford lists the Regular Cab with the 6.5 ft or 8 ft box, the SuperCab with the 6.5 ft box and the SuperCrew with the 5.5 ft or 6.5 ft box."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 comes with three boxes. The 5.5 ft box is 67.1 in long at the floor, the 6.5 ft box 78.9 in and the 8 ft box 97.6 in. All three are 50.6 in wide between the wheelhouses and 21.4 in deep.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "Earlier model years are not on this page yet.", "sections": [{"id": "box", "h": "F-150 box dimensions (2026)", "table": {"head": ["Measurement", "5.5 ft box", "6.5 ft box", "8 ft box"], "rows": [["Inside length at the floor", "67.1 in (Raptor 67.2 in)", "78.9 in", "97.6 in", 1], ["Width between the wheelhouses", "50.6 in", "50.6 in", "50.6 in", 1], ["Inside height at the molding", "21.4 in", "21.4 in", "21.4 in", 1], ["Cargo box volume", "52.8 cu ft", "62.3 cu ft", "77.4 cu ft", 1]]}, "notes": ["Ford's sheet does not list the wall-to-wall width of the box."]}, {"id": "cabs", "h": "Which cab comes with which box (2026)", "table": {"head": ["Cab", "Box", "Wheelbase"], "rows": [["Regular Cab", "6.5 ft", "122.8 in", 1], ["Regular Cab", "8 ft", "141.5 in", 1], ["SuperCab", "6.5 ft", "145.4 in", 1], ["SuperCrew", "5.5 ft", "145.4 in (Tremor 145.6 in)", 1], ["SuperCrew", "6.5 ft", "157.2 in", 1]]}}], "check": ["Measure the floor from the bulkhead to the inside of the closed tailgate: about 67 in is the 5.5 ft box, 79 in the 6.5 ft box and 98 in the 8 ft box.", "Tonneau covers, bed racks and bed mats are sold by box length. Order by the measured length, not by the cab.", "A cover for one box length does not fit another, even on the same model year.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
