INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'ground-clearance', $s$Ford$s$, $s$F-150$s$, $s$Ground clearance$s$, $s$Ford F-150 Ground Clearance by Cab and Drivetrain (2026)$s$, $s$Ford F-150 Ground Clearance by Cab and Drive (2026)$s$, $s$Ford F-150 ground clearance from Ford's 2026 spec sheet: 8.2 to 8.5 in with 4x2, 8.8 to 9.8 in with 4x4, 10.7 in on Tremor, 11.9 or 13.1 in on Raptor.$s$, $s$[{"q": "What is the ground clearance of a 2026 Ford F-150?", "a": "Ford lists 8.2 to 8.5 inches for 4x2 trucks and 9.8 inches for most 4x4 trucks. The SuperCrew 4x4 with the 6.5-ft box is listed at 8.8 inches."}, {"q": "How much ground clearance does the F-150 Tremor have?", "a": "10.7 inches, by Ford's 2026 specification sheet."}, {"q": "How much ground clearance does the F-150 Raptor have?", "a": "Ford prints two figures in the Raptor column, 11.9 and 13.1 inches, under a heading that reads 35-inch/37-inch tire."}, {"q": "Do bigger tires change ground clearance?", "a": "Yes. Ford's figures are for the truck as built. Different tires, a lift or leveling kit, or a loaded bed change the real clearance."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 has 8.2 to 8.5 inches of ground clearance with 4x2 and 9.8 inches with 4x4 in most cab and box combinations. Ford lists 10.7 inches for the Tremor and 11.9 or 13.1 inches for the Raptor, depending on tire.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "Earlier model years. Ford's sheet gives one figure per cab, box and drivetrain; it does not break the figure down by trim, tire or package apart from Tremor and Raptor.", "sections": [{"id": "supercrew", "h": "SuperCrew, Tremor and Raptor (2026)", "table": {"head": ["Configuration", "Ground clearance", "Approach angle", "Ramp breakover angle", "Departure angle"], "rows": [["SuperCrew 5.5-ft box, 4x2", "8.2 in", "23.3°", "17.1°", "24.3°", 1], ["SuperCrew 5.5-ft box, 4x4", "9.8 in", "25.9°", "19.8°", "24.9°", 1], ["SuperCrew 6.5-ft box, 4x2", "8.5 in", "22.3°", "17.1°", "24.3°", 1], ["SuperCrew 6.5-ft box, 4x4", "8.8 in", "25.9°", "19.8°", "24.9°", 1], ["Tremor 5.5-ft box, 4x4", "10.7 in", "27.6°", "21.1°", "24.1°", 1], ["Raptor 5.5-ft box, 4x4 (35\"/37\" tire)", "11.9/13.1 in", "30.7/33.1", "22.3/24.4", "23.5/24.9", 1]]}, "notes": ["The Raptor cells hold two values each, printed with a slash under Ford's column heading \"(35\"/37\" tire)\". They are shown here as Ford prints them."]}, {"id": "supercab", "h": "SuperCab, 6.5-ft box (2026)", "table": {"head": ["Configuration", "Ground clearance", "Approach angle", "Ramp breakover angle", "Departure angle"], "rows": [["SuperCab 6.5-ft box, 4x2", "8.2 in", "22.5°", "17.3°", "24.4°", 1], ["SuperCab 6.5-ft box, 4x4", "9.8 in", "25.2°", "20.0°", "26.9°", 1]]}}, {"id": "regular", "h": "Regular Cab (2026)", "table": {"head": ["Configuration", "Ground clearance", "Approach angle", "Ramp breakover angle", "Departure angle"], "rows": [["Regular Cab 6.5-ft box, 4x2", "8.3 in", "20.7°", "20.1°", "23.9°", 1], ["Regular Cab 6.5-ft box, 4x4", "9.8 in", "23.7°", "23.3°", "26.0°", 1], ["Regular Cab 8-ft box, 4x2", "8.2 in", "20.8°", "17.9°", "23.5°", 1], ["Regular Cab 8-ft box, 4x4", "9.8 in", "23.9°", "20.7°", "26.1°", 1]]}}], "check": ["Find your cab, box length and drivetrain on the window sticker, then read the matching row.", "The figures are for an unmodified truck. Running boards, a hitch or a lower air dam can sit lower than the listed clearance point.", "To measure your own truck, park on level ground and measure from the ground to the lowest fixed point under the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "hitches"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
