INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'oil-type-capacity', $s$Ford$s$, $s$F-150$s$, $s$Oil capacity$s$, $s$Ford F-150 Oil Capacity by Engine (2026)$s$, $s$Ford F-150 Oil Capacity by Engine (2026)$s$, $s$Ford F-150 engine oil capacity from Ford's 2026 spec sheet: 6.0 quarts for the 2.7L and 3.5L V6 engines, 7.75 quarts for the 5.0L V8.$s$, $s$[{"q": "How much oil does a 2026 F-150 5.0L V8 take?", "a": "7.75 quarts (7.33 liters), by Ford's 2026 specification sheet."}, {"q": "How much oil does the 3.5L EcoBoost F-150 take?", "a": "6.0 quarts (5.7 liters). Ford lists the same figure for the 2.7L EcoBoost, the 3.5L PowerBoost hybrid and the 3.5L EcoBoost High Output."}, {"q": "How much oil does the 5.2L supercharged V8 take?", "a": "Ford lists 11.5 quarts (10.9 liters) for that engine."}, {"q": "What type of oil does the F-150 use?", "a": "Ford's specification sheet gives capacity only. The oil grade and specification for your engine are in the capacities and specifications section of the owner's manual, and the grade is usually printed on the oil filler cap."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 takes 6.0 quarts of engine oil with the 2.7L and 3.5L V6 engines, 7.75 quarts with the 5.0L V8 and 11.5 quarts with the 5.2L supercharged V8, according to Ford's specification sheet. The sheet does not print the oil grade.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "The oil grade (viscosity and specification) for any year, and capacities for earlier model years: Ford's 2026 sheet prints capacity only.", "sections": [{"id": "oil", "h": "Engine oil capacity by engine (2026)", "table": {"head": ["Engine", "Oil capacity (quarts)", "Oil capacity (liters)"], "rows": [["2.7L EcoBoost V6", "6.0 qt", "5.7 L", 1], ["5.0L V8", "7.75 qt", "7.33 L", 1], ["3.5L EcoBoost V6", "6.0 qt", "5.7 L", 1], ["3.5L PowerBoost Full Hybrid V6", "6.0 qt", "5.7 L", 1], ["3.5L EcoBoost V6 High Output", "6.0 qt", "5.7 L", 1], ["5.2L supercharged V8", "11.5 qt", "10.9 L", 1]]}, "notes": ["Ford's sheet does not say whether these figures include the oil filter."]}], "check": ["Look up the oil grade and specification in the capacities and specifications section of your owner's manual before you buy oil.", "After an oil change, fill short of the listed capacity, run the engine briefly, wait, then top up to the upper mark on the dipstick.", "Your engine is named on the window sticker and in the owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["floor-mats", "seat-covers"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
