INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'tire-size', $s$Ford$s$, $s$F-150$s$, $s$Tire size$s$, $s$Ford F-150 Tire Size by Trim (2026)$s$, $s$Ford F-150 Tire Size by Trim (2026)$s$, $s$Ford F-150 tire sizes from Ford's 2026 spec sheet, by trim and drivetrain: 245/70R17 on XL and XLT 4x2 up to 275/50R22 and 37x12.5R17 options.$s$, $s$[{"q": "What size tires come on a 2026 Ford F-150?", "a": "It depends on trim and drivetrain. Ford's standard list runs from 245/70R17 on the XL and XLT 4x2 to 275/60R20 on the King Ranch and Platinum."}, {"q": "What size tires are on a 2026 F-150 XLT?", "a": "Ford lists 245/70R17 all-season as standard on the XLT 4x2 and 275/65R18 all-terrain on the XLT 4x4. 265/60R18 (4x2) and 265/70R18C (4x4) are listed as options."}, {"q": "What size tires does the F-150 Tremor use?", "a": "275/70R18 all-terrain, by Ford's 2026 sheet."}, {"q": "Which F-150 has 22-inch tires?", "a": "Ford lists 275/50R22 all-season as optional with the STX Lobo Package and on the King Ranch and Platinum."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 comes with tires from 245/70R17 (XL and XLT 4x2) to 275/60R20 (King Ranch and Platinum) as standard, with 275/50R22 and 37x12.5R17 among the options. The size depends on trim and on 4x2 or 4x4.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "Earlier model years, tire pressures and load ratings. The Raptor's base tire is left out: the two readings of Ford's sheet did not agree on whether it is listed as standard or optional.", "sections": [{"id": "standard", "h": "Standard tires by trim (2026)", "table": {"head": ["Tire", "Trim and drivetrain"], "rows": [["245/70R17 all-season", "XL, XLT 4x2", 1], ["265/70R17 all-terrain", "XL 4x4", 1], ["265/60R18 all-season", "STX, Lariat 4x2", 1], ["275/65R18 all-terrain", "STX, XLT, Lariat 4x4", 1], ["275/70R18 all-terrain", "Tremor", 1], ["275/60R20 all-season", "King Ranch, Platinum 4x2", 1], ["275/60R20 all-terrain", "King Ranch, Platinum 4x4", 1]]}}, {"id": "optional", "h": "Optional tires (2026)", "table": {"head": ["Tire", "Trim or package"], "rows": [["265/70R17C all-terrain", "XL Fleet, FX4 Package", 1], ["265/60R18 all-season", "XLT 4x2", 1], ["265/70R18C all-terrain", "XLT 4x4", 1], ["275/60R20 all-season", "STX, Lariat 4x2", 1], ["275/60R20 all-terrain", "STX, Lariat 4x4", 1], ["275/50R22 all-season", "STX Lobo Package, King Ranch, Platinum", 1], ["37x12.5R17 all-terrain", "Raptor 37 Package", 1]]}}], "check": ["Read the size molded into the sidewall of the tires on your truck: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure for your truck.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
