INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'f-150', 'towing-capacity', $s$Ford$s$, $s$F-150$s$, $s$Towing capacity$s$, $s$Ford F-150 Towing Capacity by Engine (2026)$s$, $s$Ford F-150 Towing Capacity by Engine (2026)$s$, $s$Ford F-150 towing capacity from Ford's 2026 spec sheet: up to 13,500 lb with the 3.5L EcoBoost, 8,200 to 12,800 lb with the other engines.$s$, $s$[{"q": "What is the maximum towing capacity of a 2026 F-150?", "a": "13,500 lb, with the 3.5L EcoBoost V6 and 4x4. Ford's sheet attaches a condition: a SuperCrew with the Max Tow/Haul Package and the Max Tow Axle upgrade."}, {"q": "How much can an F-150 with the 2.7L EcoBoost tow?", "a": "Up to 8,400 lb with 4x2 and 8,200 lb with 4x4, by Ford's 2026 sheet."}, {"q": "How much can the F-150 hybrid tow?", "a": "The 3.5L PowerBoost is listed at up to 12,400 lb with 4x2 and 11,600 lb with 4x4, with the same package condition as the other high figures."}, {"q": "How much can a Raptor tow?", "a": "Ford lists 8,200 lb for the 3.5L EcoBoost High Output and 8,700 lb for the 5.2L supercharged V8, both 4x4."}, {"q": "Will my F-150 tow the maximum figure?", "a": "Only if it is built the way the footnote says. Cab, box, axle ratio and packages all change the rating; the figure for your truck is in the towing section of its owner's manual and on its labels."}]$s$::jsonb, $s${"answer": "The 2026 Ford F-150 tows up to 13,500 lb with the 3.5L EcoBoost V6. The other engines top out between 8,200 and 12,800 lb. These are maximum figures by engine: Ford ties the highest ones to a SuperCrew with the Max Tow/Haul Package and the Max Tow Axle upgrade.", "reviewed": "2026-11-19", "covers": "Model year 2026", "not_covered": "Earlier model years, and the breakdown by cab, box and axle ratio: Ford's sheet gives the maximum per engine only.", "sections": [{"id": "towing", "h": "Maximum conventional towing by engine (2026)", "table": {"head": ["Engine", "4x2", "4x4"], "rows": [["2.7L EcoBoost V6", "8,400 lb", "8,200 lb", 1], ["5.0L V8", "12,800 lb", "12,800 lb", 1], ["3.5L EcoBoost V6", "13,300 lb", "13,500 lb", 1], ["3.5L PowerBoost Full Hybrid V6", "12,400 lb", "11,600 lb", 1], ["3.5L EcoBoost V6 High Output", "—", "8,200 lb", 1], ["5.2L supercharged V8", "—", "8,700 lb", 1]]}, "notes": ["Ford's footnote on these figures: F-150 SuperCrew, requires the Max Tow/Haul Package (53T) and the optional Max Tow Axle upgrade. It applies to the 5.0L, 3.5L EcoBoost and PowerBoost figures.", "A dash means Ford lists no 4x2 figure. Ford also notes that maximum towing, payload, horsepower and torque are separate ratings that may not be reached at the same time."]}], "check": ["Find the engine on your window sticker, then check whether the truck has the Max Tow/Haul Package. Without it, the rating is lower than the maximum here.", "Use the towing tables in your owner's manual: they list the rating by cab, box, drivetrain and axle ratio.", "Add the trailer's tongue weight to passengers and cargo, and keep the total under the payload on the yellow door-jamb label.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "tonneau-covers", "running-boards"], "sources": [["Ford, 2026 F-150 Technical Specifications (v1.1, 31 Mar 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_F150_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-19', TIMESTAMPTZ '2026-11-19 10:00:00+06', 'model', '')
