INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'maverick', 'oil-type-capacity', $s$Ford$s$, $s$Maverick$s$, $s$Oil capacity$s$, $s$Ford Maverick Oil Capacity: Hybrid and EcoBoost (2026)$s$, $s$Ford Maverick Oil Capacity: Hybrid and EcoBoost (2026)$s$, $s$Ford Maverick engine oil capacity from Ford's 2026 spec sheet: 5.7 quarts for the 2.5L Hybrid and 6.1 quarts for the 2.0L EcoBoost.$s$, $s$[{"q": "How much oil does a 2026 Ford Maverick take?", "a": "Ford's 2026 specification sheet lists an oil capacity of 5.7 quarts for the 2.5L Hybrid and 6.1 quarts for the 2.0L EcoBoost."}, {"q": "What type of oil does the Maverick use?", "a": "Ford's specification sheet gives the capacity only. The oil grade and specification for your engine are in the capacities and specifications section of the owner's manual, and the grade is usually printed on the oil filler cap."}, {"q": "Do the Tremor and Lobo take a different amount?", "a": "The sheet lists oil capacity by engine, not by trim. A Tremor or Lobo takes the amount listed for its engine."}]$s$::jsonb, $s${"answer": "The 2026 Ford Maverick has an engine oil capacity of 5.7 quarts with the 2.5L Hybrid and 6.1 quarts with the 2.0L EcoBoost, according to Ford's specification sheet. The sheet does not print the oil grade.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "The oil grade (viscosity and specification) for any year, and capacities for 2022 to 2025: Ford's 2026 sheet prints capacity only.", "sections": [{"id": "oil", "h": "Engine oil capacity by engine (2026)", "table": {"head": ["Engine", "Oil capacity"], "rows": [["2.5L Hybrid", "5.7 qt", 1], ["2.0L EcoBoost I-4", "6.1 qt", 1]]}, "notes": ["Ford's sheet does not say whether these figures include the oil filter."]}], "check": ["Look up the oil grade and specification in the capacities and specifications section of your owner's manual before you buy oil.", "After an oil change, fill short of the listed capacity, run the engine briefly, wait, then top up to the upper mark on the dipstick.", "Your engine is named on the window sticker and in the owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["floor-mats", "seat-covers"], "sources": [["Ford, 2026 Maverick Technical Specifications (v1.2, 20 Jul 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
