INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'maverick', 'payload-capacity', $s$Ford$s$, $s$Maverick$s$, $s$Payload capacity$s$, $s$Ford Maverick Payload Capacity by Powertrain (2026)$s$, $s$Ford Maverick Payload Capacity by Powertrain (2026)$s$, $s$Ford Maverick payload capacity from Ford's 2026 spec sheet: up to 1,500 lb, 1,400 lb on the Hybrid AWD, 1,140 lb on Tremor and 1,045 lb on Lobo.$s$, $s$[{"q": "What is the payload capacity of a 2026 Ford Maverick?", "a": "Ford lists a maximum payload of 1,500 lb for the 2.5L Hybrid with FWD and for the 2.0L EcoBoost with FWD or AWD. The Hybrid AWD is listed at 1,400 lb."}, {"q": "How much payload do the Tremor and Lobo have?", "a": "Ford's 2026 sheet lists a maximum payload of 1,140 lb for the Tremor and 1,045 lb for the Lobo."}, {"q": "Does payload include passengers?", "a": "Yes. Payload is everything the truck carries: people, cargo in the cab and bed, accessories added after the build, and the tongue weight of a trailer."}, {"q": "Where is the payload figure for my own Maverick?", "a": "On the Tire and Loading Information label on the driver's door jamb. Ford's sheet says maximum payload varies with accessories and vehicle configuration and points to that label for a specific vehicle."}]$s$::jsonb, $s${"answer": "The 2026 Ford Maverick carries a maximum payload of 1,500 lb in most versions. Ford's specification sheet lists 1,400 lb for the Hybrid AWD, 1,140 lb for the Tremor and 1,045 lb for the Lobo.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "2022 to 2025: Ford's sheets for these years are not on this page yet.", "sections": [{"id": "payload", "h": "Maximum payload, GVWR and curb weight (2026)", "table": {"head": ["Powertrain or trim", "Maximum payload", "GVWR", "Base curb weight"], "rows": [["2.5L Hybrid, FWD", "1,500 lb", "5,230 lb", "3,667 lb", 1], ["2.5L Hybrid, AWD", "1,400 lb", "5,330 lb", "3,838 lb", 1], ["2.0L EcoBoost, FWD", "1,500 lb", "5,100 lb", "3,517 lb", 1], ["2.0L EcoBoost, AWD", "1,500 lb", "5,240 lb", "3,652 lb", 1], ["Tremor (AWD)", "1,140 lb", "5,090 lb", "3,890 lb", 1], ["Lobo (AWD)", "1,045 lb", "4,970 lb", "3,814 lb", 1]]}, "notes": ["Ford's footnote on the payload figures: maximum payload varies and is based on accessories and vehicle configuration; the label on the door jamb gives the carrying capacity of a specific vehicle.", "Ford also notes that payload, towing, horsepower and torque are separate ratings that may not be reached at the same time."]}], "check": ["Read the yellow Tire and Loading Information label on the driver's door jamb. It gives the combined weight of occupants and cargo your truck should never exceed.", "Add up passengers, cargo, accessories fitted after the truck was built and any trailer tongue weight, and keep the total under that label figure.", "A tonneau cover, bed rack or hitch counts against payload once it is on the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Ford, 2026 Maverick Technical Specifications (v1.2, 20 Jul 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
