INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'maverick', 'tire-size', $s$Ford$s$, $s$Maverick$s$, $s$Tire size$s$, $s$Ford Maverick Tire Size by Trim (2026)$s$, $s$Ford Maverick Tire Size by Trim (2026)$s$, $s$Ford Maverick tire sizes from Ford's 2026 spec sheet: 225/65R17 on XL and XLT, 235/65R17 on Tremor, 225/55R19 on Lariat and Lobo.$s$, $s$[{"q": "What size tires are on a 2026 Ford Maverick?", "a": "Ford lists 225/65R17 all-season tires on the XL and XLT, 235/65R17 all-terrain tires on the Tremor, and 225/55R19 all-season tires on the Lariat and Lobo."}, {"q": "What tires come with the FX4 Off-Road Package?", "a": "Ford's 2026 sheet lists 225/65R17 all-terrain tires as included in the FX4 Off-Road Package."}, {"q": "What size is the Maverick spare tire?", "a": "Ford lists a 215/70R17 all-terrain spare, included in the 4K Tow Package and standard on the Tremor. The sheet does not describe the spare on other versions."}, {"q": "What wheel size does the Maverick use?", "a": "17-inch wheels on the XL, XLT and Tremor and 19-inch wheels on the Lariat and Lobo, by the same sheet."}]$s$::jsonb, $s${"answer": "The 2026 Ford Maverick uses 225/65R17 tires on the XL and XLT, 235/65R17 all-terrain tires on the Tremor and 225/55R19 tires on the Lariat and Lobo, according to Ford's specification sheet.", "reviewed": "2026-11-20", "covers": "Model year 2026", "not_covered": "2022 to 2025, tire pressures and load ratings: Ford's sheet does not print them, and the earlier years are not on this page yet.", "sections": [{"id": "tires", "h": "Tire sizes by trim (2026)", "table": {"head": ["Tire", "Trim or package", "Ford lists it as"], "rows": [["225/65R17 all-season", "XL, XLT", "Standard", 1], ["235/65R17 all-terrain", "Tremor", "Standard", 1], ["225/55R19 all-season", "Lariat and Lobo; included in Black Appearance Package", "Standard", 1], ["225/65R17 all-terrain", "Included in FX4 Off-Road Package", "Optional", 1], ["215/70R17 all-terrain (spare)", "Included in 4K Tow Package; standard on Tremor", "Spare", 1]]}}, {"id": "wheels", "h": "Wheels by trim (2026)", "table": {"head": ["Wheel", "Trim or package", "Ford lists it as"], "rows": [["17\" Sparkle Silver-painted steel", "XL", "Standard", 1], ["17\" Carbonized Gray-painted aluminum", "XLT", "Standard", 1], ["17\" machined-face Dark Tarnish-painted aluminum with orange-painted pocket", "Tremor", "Standard", 1], ["19\" painted aluminum", "Lariat", "Standard", 1], ["19\" black-painted, turbofan-styled aluminum", "Lobo", "Standard", 1], ["19\" black-painted aluminum", "Included in Black Appearance Package; optional on Lobo", "Optional", 1]]}}], "check": ["Read the size molded into the sidewall of the tires on your truck: a previous owner may have changed them.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and the cold inflation pressure for your truck.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Ford, 2026 Maverick Technical Specifications (v1.2, 20 Jul 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Maverick_Specs.pdf"]]}$s$::jsonb, 'published', DATE '2026-11-21', TIMESTAMPTZ '2026-11-21 10:00:00+06', 'model', '')
