VALUES ('ford', 'ranger', 'ground-clearance', $s$Ford$s$, $s$Ranger$s$, $s$Ground clearance$s$, $s$Ford Ranger Ground Clearance: 9.3 in, or 10.7 in for the Raptor (2026)$s$, $s$Ford Ranger Ground Clearance and Angles (2026)$s$, $s$Ford Ranger ground clearance from Ford's 2026 spec sheet: 9.3 in with 4x2 or 4x4 and 10.7 in on the Raptor, with approach, breakover and departure angles.$s$, $s$[{"q": "What is the ground clearance of a 2026 Ford Ranger?", "a": "9.3 inches with either 4x2 or 4x4, by Ford's 2026 specification sheet."}, {"q": "How much ground clearance does the Ranger Raptor have?", "a": "10.7 inches. Ford also lists a 33.0° approach angle, a 24.2° ramp breakover angle and a 26.4° departure angle for the Raptor."}, {"q": "Does 4x4 raise the Ranger?", "a": "Not in Ford's 2026 sheet: the 4x2 and 4x4 columns print the same 9.3 inches and the same three angles."}, {"q": "Do bigger tires change ground clearance?", "a": "Yes. Ford's figures are for the truck as built. Different tires, a lift or leveling kit, or a loaded bed change the real clearance."}]$s$::jsonb, $s${"answer": "The 2026 Ford Ranger has 9.3 inches of ground clearance with 4x2 or 4x4, according to Ford's specification sheet. The Ranger Raptor has 10.7 inches.", "covers": "Model year 2026", "not_covered": "2019 to 2025. Ford's sheet gives one figure each for 4x2, 4x4 and Raptor; it does not break the figure down by series, tire or package.", "sections": [{"id": "clearance", "h": "Ground clearance and off-road angles (2026)", "table": {"head": ["Version", "Ground clearance", "Approach angle", "Ramp breakover angle", "Departure angle"], "rows": [["4x2", "9.3 in", "30.2°", "23.0°", "25.8°", 1], ["4x4", "9.3 in", "30.2°", "23.0°", "25.8°", 1], ["Raptor 4x4", "10.7 in", "33.0°", "24.2°", "26.4°", 1]]}, "notes": ["Ford's table is headed in inches unless otherwise noted and attaches no footnote to these rows."]}], "check": ["Check whether your truck is a Raptor: it is the only version with its own figures.", "The figures are for an unmodified truck. Running boards, a hitch or a lower air dam can sit lower than the listed clearance point.", "To measure your own truck, park on level ground and measure from the ground to the lowest fixed point under the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "hitches"], "sources": [["Ford, 2026 Ranger Technical Specifications (v1.0, 13 Jan 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Ranger%20Technical_Specs.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
