INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ford', 'ranger', 'payload-capacity', $s$Ford$s$, $s$Ranger$s$, $s$Payload capacity$s$, $s$Ford Ranger Payload Capacity by Engine (2026)$s$, $s$Ford Ranger Payload Capacity by Engine (2026)$s$, $s$Ford Ranger payload capacity from Ford's 2026 spec sheet: up to 1,763 lb with the 2.3L 4x4, 1,513 lb with the 2.7L V6 and 1,373 lb for the Raptor.$s$, $s$[{"q": "What is the payload capacity of a 2026 Ford Ranger?", "a": "Ford's 2026 specification sheet lists an available maximum 4x4 payload of 1,763 lb with the 2.3L EcoBoost, 1,513 lb with the 2.7L EcoBoost V6 and 1,373 lb with the 3.0L EcoBoost V6 of the Raptor."}, {"q": "Does the V6 Ranger carry less than the four-cylinder?", "a": "Yes, by Ford's sheet: it prints a lower maximum for the 2.7L and the lowest for the Raptor. The sheet does not explain the difference."}, {"q": "Does payload include passengers and tongue weight?", "a": "Yes. Payload is everything the truck carries: people, cargo in the cab and bed, accessories added after the build, and the tongue weight of a trailer."}, {"q": "Where is the payload for my own Ranger?", "a": "On the label on the driver's door jamb. Ford's footnote says maximum payload varies with accessories and vehicle configuration and points to that label for a specific vehicle."}]$s$::jsonb, $s${"answer": "The 2026 Ford Ranger carries up to 1,763 lb of payload with the 2.3L EcoBoost and 4x4. Ford's specification sheet lists 1,513 lb for the 2.7L EcoBoost V6 and 1,373 lb for the Ranger Raptor. These are the available maximum 4x4 figures by engine.", "covers": "Model year 2026", "not_covered": "2019 to 2025, and 4x2 trucks: the figures here are the 4x4 maximums Ford prints by engine. A breakdown by series is not in Ford's sheet.", "sections": [{"id": "payload", "h": "Available maximum 4x4 payload by engine (2026)", "table": {"head": ["Engine", "Available maximum 4x4 payload"], "rows": [["2.3L EcoBoost I-4", "1,763 lb", 1], ["2.7L EcoBoost V6", "1,513 lb", 1], ["3.0L EcoBoost V6 (Raptor)", "1,373 lb", 1]]}, "notes": ["Ford's footnote on these figures: maximum payload varies and is based on accessories and vehicle configuration; the label on the door jamb gives the carrying capacity of a specific vehicle.", "Ford also notes that horsepower, torque, payload and towing are separate ratings that may not be reached at the same time."]}], "check": ["Read the Tire and Loading Information label on the driver's door jamb. It gives the combined weight of occupants and cargo your truck should never exceed.", "Add up passengers, cargo, accessories fitted after the truck was built and any trailer tongue weight, and keep the total under that label figure.", "A tonneau cover, bed rack or hitch counts against payload once it is on the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Ford, 2026 Ranger Technical Specifications (v1.0, 13 Jan 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Ranger%20Technical_Specs.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
