VALUES ('ford', 'ranger', 'tire-size', $s$Ford$s$, $s$Ranger$s$, $s$Tire size$s$, $s$Ford Ranger Tire Size by Series (2026)$s$, $s$Ford Ranger Tire Size by Series (2026)$s$, $s$Ford Ranger tire sizes from Ford's 2026 spec sheet: 255/70R17 on XL and XLT, 255/65R18 on Lariat, LT285/70R17 on Raptor, LT255/70R17 with FX4.$s$, $s$[{"q": "What size tires come on a 2026 Ford Ranger?", "a": "Ford's 2026 sheet lists 255/70R17 all-terrain for the XL and XLT, 255/65R18 all-terrain for the Lariat and LT285/70R17 all-terrain for the Raptor."}, {"q": "What tires come with the FX4 Off-Road Package?", "a": "Ford lists LT255/70R17 all-terrain outlined-white-letter tires as an option, marked for the XLT with the FX4 Off-Road Package only."}, {"q": "What size tires are on a Ranger Raptor?", "a": "LT285/70R17 all-terrain, by Ford's 2026 sheet."}, {"q": "Where do I find the tire pressure?", "a": "On the Tire and Loading Information label on the driver's door jamb. Ford's specification sheet prints sizes only, not pressures."}]$s$::jsonb, $s${"answer": "The 2026 Ford Ranger comes on 255/70R17 all-terrain tires as an XL or XLT, 255/65R18 as a Lariat and LT285/70R17 as a Raptor, according to Ford's specification sheet. An LT255/70R17 tire is listed for the XLT with the FX4 Off-Road Package.", "covers": "Model year 2026", "not_covered": "2019 to 2025, tire pressures and load ratings. Ford prints a standard and an optional column; for the Lariat and Raptor lines the two readings of the sheet could not confirm the column, so this page names the series only.", "sections": [{"id": "tires", "h": "Tires by series (2026)", "table": {"head": ["Tire", "Series, as Ford prints it"], "rows": [["255/70R17 all-terrain", "XL, XLT", 1], ["255/65R18 all-terrain", "Lariat", 1], ["LT285/70R17 all-terrain", "Raptor", 1], ["LT255/70R17 all-terrain OWL", "XLT with FX4 Off-Road Package only", 1]]}, "notes": ["Ford lists the 255/70R17 tire as standard and the LT255/70R17 tire as optional. OWL means outlined white letters."]}], "check": ["Read the size molded into the sidewall of the tires on your truck: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure for your truck.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Ford, 2026 Ranger Technical Specifications (v1.0, 13 Jan 2026)", "https://www.fromtheroad.ford.com/content/dam/fordmediasite/us/en/library/2026/specs/2026_Ford_Ranger%20Technical_Specs.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
