VALUES ('honda', 'pilot', 'gas-tank-size', $s$Honda$s$, $s$Pilot$s$, $s$Gas tank size$s$, $s$Honda Pilot Gas Tank Size: 18.5 Gallons (2026)$s$, $s$Honda Pilot Gas Tank Size: 18.5 Gallons (2026)$s$, $s$Honda Pilot gas tank size from Honda's 2026 specification sheet and owner's manual: 18.5 US gallons (70.0 L) on every trim, regular unleaded.$s$, $s$[{"q": "How big is the gas tank on a 2026 Honda Pilot?", "a": "18.5 US gallons (70.0 L). Honda's 2026 specification sheet prints 18.5 gallons for all six trims and the owner's manual gives the same figure."}, {"q": "What fuel does the 2026 Pilot use?", "a": "Regular unleaded. The owner's manual specifies unleaded gasoline with a pump octane number of 87 or higher."}]$s$::jsonb, $s${"answer": "The 2026 Honda Pilot has an 18.5-gallon (70.0 L) fuel tank on every trim, according to Honda's specification sheet and the owner's manual. Honda specifies regular unleaded gasoline, pump octane 87 or higher.", "covers": "Model year 2026", "not_covered": "2023 to 2025 and earlier generations: Honda's figures for those years are not on this page yet.", "sections": [{"id": "tank", "h": "Fuel tank capacity (2026)", "table": {"head": ["Item", "Figure", "Applies to"], "rows": [["Fuel tank capacity", "18.5 US gal", "Sport, EX-L, TrailSport, Touring, Elite, Black Edition", 1], ["Fuel tank capacity", "18.5 US gal (70.0 L)", "Pilot, owner's manual specifications", 2], ["Recommended fuel", "Regular unleaded", "All six trims", 1], ["Fuel type", "Unleaded gasoline, pump octane number 87 or higher", "Pilot, owner's manual specifications", 2]]}}], "check": ["The tank figure is total capacity; the low-fuel warning comes on with fuel still in the tank.", "The octane requirement is also printed in your owner's manual.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "hitches"], "sources": [["Honda Newsroom, 2026 Honda Pilot Specifications & Features (26 Jan 2026)", "https://hondanews.com/en-US/honda-automobiles/releases/release-14c469388b7fed5af247fc02e2009aa7-2026-honda-pilot-specifications-features"], ["Honda, Pilot online owner's manual (publication AT902626IOM, 2026 Pilot), Specifications", "https://techinfo.honda.com/rjanisis/pubs/om/ah/at902626iom/enu/details/131293047-16992.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
