VALUES ('honda', 'pilot', 'ground-clearance', $s$Honda$s$, $s$Pilot$s$, $s$Ground clearance$s$, $s$Honda Pilot Ground Clearance: 7.3 in, 8.3 in TrailSport (2026)$s$, $s$Honda Pilot Ground Clearance: 7.3 or 8.3 in (2026)$s$, $s$Honda Pilot ground clearance from Honda's 2026 specification sheet: 7.3 in unladen on most trims and 8.3 in on the TrailSport.$s$, $s$[{"q": "What is the ground clearance of a 2026 Honda Pilot?", "a": "7.3 in unladen on Sport, EX-L, Touring, Elite and Black Edition, and 8.3 in on the TrailSport, by Honda's 2026 specification sheet."}, {"q": "Does AWD change the Pilot's ground clearance?", "a": "Not on the trims sold both ways. Honda prints 7.3 in for both the 2WD and AWD versions of the Sport and EX-L."}]$s$::jsonb, $s${"answer": "The 2026 Honda Pilot has 7.3 in of ground clearance on every trim except the TrailSport, which has 8.3 in, according to Honda's specification sheet. Honda states the figures unladen.", "covers": "Model year 2026", "not_covered": "2023 to 2025 and earlier generations: Honda's figures for those years are not on this page yet.", "sections": [{"id": "clearance", "h": "Ground clearance, unladen (2026)", "table": {"head": ["Trim", "2WD", "AWD"], "rows": [["Sport", "7.3 in", "7.3 in", 1], ["EX-L", "7.3 in", "7.3 in", 1], ["TrailSport", "NA", "8.3 in", 1], ["Touring", "NA", "7.3 in", 1], ["Elite", "NA", "7.3 in", 1], ["Black Edition", "NA", "7.3 in", 1]]}, "notes": ["\"NA\" is how Honda's sheet marks the 2WD column for the four trims it lists with all-wheel drive only.", "Unladen means without passengers or cargo; a loaded Pilot sits lower."]}], "check": ["Check your trim badge: only the TrailSport has the 8.3 in figure.", "Measure your own vehicle on level ground at the lowest point under the body if you need an exact number.", "A different tire size or a lift kit changes the figure.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Honda Newsroom, 2026 Honda Pilot Specifications & Features (26 Jan 2026)", "https://hondanews.com/en-US/honda-automobiles/releases/release-14c469388b7fed5af247fc02e2009aa7-2026-honda-pilot-specifications-features"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
