INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('honda', 'pilot', 'oil-type-capacity', $s$Honda$s$, $s$Pilot$s$, $s$Oil type and capacity$s$, $s$Honda Pilot Oil Type and Capacity: 0W-20, 5.8 Quarts (2026)$s$, $s$Honda Pilot Oil Type & Capacity: 0W-20, 5.8 qt (2026)$s$, $s$Honda Pilot oil type and capacity from Honda's 2026 owner's manual: 0W-20, 5.8 US quarts (5.5 L) with a filter change, 5.5 quarts without.$s$, $s$[{"q": "What oil does a 2026 Honda Pilot take?", "a": "0W-20. The owner's manual recommends Honda Genuine Motor Oil 0W-20, or an API service SN or higher grade 0W-20 oil."}, {"q": "How much oil does a 2026 Honda Pilot hold?", "a": "5.8 US quarts (5.5 L) for a change including the filter, and 5.5 US quarts (5.2 L) for a change without it, by Honda's owner's manual."}, {"q": "Which engine does that apply to?", "a": "The Pilot's 3.5-liter V6. The manual lists a displacement of 3,471 cm3 and gives a single oil specification."}]$s$::jsonb, $s${"answer": "The 2026 Honda Pilot takes 0W-20 engine oil: 5.8 US quarts (5.5 L) for a change including the filter, or 5.5 US quarts (5.2 L) without, according to Honda's owner's manual. Honda recommends Honda Genuine Motor Oil 0W-20 or an API service SN or higher grade 0W-20.", "covers": "Model year 2026", "not_covered": "2023 to 2025 and earlier generations: Honda's manuals for those years have not been read for this page yet.", "sections": [{"id": "oil", "h": "Engine oil (2026)", "table": {"head": ["Item", "As Honda's manual prints it"], "rows": [["Recommended oil", "Honda Genuine Motor Oil 0W-20", 1], ["Alternative", "API service SN or higher grade 0W-20", 1], ["Capacity, change", "5.5 US qt (5.2 L)", 1], ["Capacity, change including filter", "5.8 US qt (5.5 L)", 1], ["Engine displacement", "211.7 cu-in (3,471 cm3)", 1]]}, "notes": ["The specifications page of Honda's online manual names the model (Pilot) but not the year; Honda lists this manual as the 2026 Pilot owner's manual, and its figures match Honda's 2026 specification sheet (3,471 cc engine, 18.5-gallon tank)."]}], "check": ["After a change, run the engine, wait a few minutes and read the dipstick; fill to the upper mark, not to a quart count.", "Follow the Maintenance Minder on the dashboard for the change interval.", "The oil filler cap and the owner's manual both name the viscosity for your engine.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["floor-mats", "seat-covers", "dash-cams"], "sources": [["Honda, Pilot online owner's manual (publication AT902626IOM, 2026 Pilot), Specifications", "https://techinfo.honda.com/rjanisis/pubs/om/ah/at902626iom/enu/details/131293047-16992.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
