VALUES ('honda', 'pilot', 'tire-size', $s$Honda$s$, $s$Pilot$s$, $s$Tire size$s$, $s$Honda Pilot Tire Size: 255/50R20, 255/60R18 or 265/60R18 (2026)$s$, $s$Honda Pilot Tire Size by Trim (2026)$s$, $s$Honda Pilot tire size from Honda's 2026 documents: 255/50R20 on Sport, Touring, Elite and Black Edition, 255/60R18 on EX-L, 265/60R18 on TrailSport.$s$, $s$[{"q": "What size tires are on a 2026 Honda Pilot?", "a": "255/50R20 on Sport, Touring, Elite and Black Edition, 255/60R18 on EX-L and 265/60R18 on TrailSport, by Honda's 2026 specification sheet."}, {"q": "What tire pressure does Honda list for the Pilot?", "a": "35 psi (240 kPa) for the regular tires, by the 2026 owner's manual. The compact spare is 60 psi (420 kPa)."}, {"q": "Does the 2026 Pilot have a full-size spare?", "a": "Only the TrailSport is listed with a full-size spare; the owner's manual gives its size as 265/60R18 110T. The other five trims are listed with a compact spare, T155/85D18 115M."}]$s$::jsonb, $s${"answer": "The 2026 Honda Pilot uses 255/50R20 tires on Sport, Touring, Elite and Black Edition, 255/60R18 on EX-L and 265/60R18 on TrailSport, according to Honda's specification sheet. The owner's manual lists 35 psi for all three sizes.", "covers": "Model year 2026", "not_covered": "2023 to 2025 and earlier generations, and the wheel bolt pattern: neither Honda document prints these.", "sections": [{"id": "by-trim", "h": "Tire and wheel by trim (2026)", "table": {"head": ["Trim", "Tire size", "Wheel", "Spare"], "rows": [["Sport", "255/50R20", "20-in. Shark Gray", "Compact", 1], ["EX-L", "255/60R18", "18-in. Pewter Gray Machined Face", "Compact", 1], ["TrailSport", "265/60R18 (Rugged Terrain)", "18-in. Shark Gray", "Full-size", 1], ["Touring", "255/50R20", "20-in. Shark Gray Machined Face", "Compact", 1], ["Elite", "255/50R20", "20-in. Shark Gray Machined Face", "Compact", 1], ["Black Edition", "255/50R20", "20-in. Gloss Black", "Compact", 1]]}}, {"id": "manual", "h": "Sizes and pressures in the owner's manual", "table": {"head": ["Item", "Size", "Pressure"], "rows": [["Regular tires", "255/60R18 108H, 265/60R18 110T, 255/50R20 105H", "35 psi (240 kPa)", 2], ["Compact spare", "T155/85D18 115M", "60 psi (420 kPa)", 2], ["Full-size spare", "265/60R18 110T", "35 psi (240 kPa)", 2], ["Regular wheels", "18 x 8J or 20 x 8J", "Not applicable", 2], ["Compact spare wheel", "18 x 4T", "Not applicable", 2]]}, "notes": ["Honda's manual: the original tire size is on the tire information label on the driver's doorjamb.", "Not every model has each spare; the manual marks both as not available on all models."]}], "check": ["Read the tire information label on the driver's doorjamb: it names the original size and pressure for your vehicle.", "Compare it with the size on your tire sidewall; a previous owner may have changed it.", "Keep the load index and speed symbol at or above the original when you replace tires.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "floor-mats", "running-boards"], "sources": [["Honda Newsroom, 2026 Honda Pilot Specifications & Features (26 Jan 2026)", "https://hondanews.com/en-US/honda-automobiles/releases/release-14c469388b7fed5af247fc02e2009aa7-2026-honda-pilot-specifications-features"], ["Honda, Pilot online owner's manual (publication AT902626IOM, 2026 Pilot), Specifications", "https://techinfo.honda.com/rjanisis/pubs/om/ah/at902626iom/enu/details/131293047-16992.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
