INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('ram', '1500', 'payload-capacity', $s$Ram$s$, $s$1500$s$, $s$Payload capacity$s$, $s$Ram 1500 Payload Capacity: Up to 2,360 lb (2026)$s$, $s$Ram 1500 Payload Capacity: Up to 2,360 lb (2026)$s$, $s$Ram 1500 payload capacity from Ram's 2026 chart: up to 2,360 lb with the 3.6L V6, 1,930 lb with the 3.0L Hurricane and 1,650 lb with the 5.7L HEMI V8.$s$, $s$[{"q": "What is the payload capacity of a 2026 Ram 1500?", "a": "Up to 2,360 lb, a figure Ram prints for the 3.6L Pentastar V6 in a Quad Cab with 4x2. Other engines and cabs are lower."}, {"q": "What is the payload of a Ram 1500 with the 5.7L HEMI?", "a": "Ram's 2026 chart prints 1,650 lb with 4x2 and 1,630 lb with 4x4, for the Crew Cab with the 5 ft 7 in bed."}, {"q": "What is the payload of the Ram 1500 RHO?", "a": "Ram's 2026 chart prints 1,490 lb for the RHO, with 4x4."}, {"q": "Can I tow the maximum and carry the maximum payload together?", "a": "No. Ram's chart states that trailer weight and payload ratings are mutually exclusive."}]$s$::jsonb, $s${"answer": "The 2026 Ram 1500 carries a maximum payload of up to 2,360 lb, a figure Ram prints for the 3.6L V6 in a Quad Cab with 4x2. The 3.0L Hurricane is listed at 1,730 to 1,930 lb, the 5.7L HEMI V8 at 1,630 to 1,650 lb and the High Output Hurricane at 1,390 lb (Limited) or 1,490 lb (RHO).", "covers": "Model year 2026", "not_covered": "2019 to 2025, the Ram 1500 Classic and the Ram 1500 REV. Other 3.6L V6 rows and one unlabelled High Output figure are left out: their cells could not be matched to cab and bed columns with certainty.", "sections": [{"id": "max", "h": "Maximum payload by engine (2026)", "intro": "Ram's chart is headed Maximum Payload Capacities. NA means Ram lists no figure.", "table": {"head": ["Engine", "GVWR (4x2/4x4)", "Cab and bed", "4x2", "4x4"], "rows": [["3.6L Pentastar V6 with eTorque", "Not stated", "Quad Cab", "2,360 lb", "NA", 1], ["3.0L Hurricane I6 twin turbo (SO)", "6,900/7,100 lb", "Quad Cab, 6'4\" bed", "1,930 lb", "1,910 lb", 1], ["3.0L Hurricane I6 twin turbo (SO)", "6,900/7,100 lb", "Crew Cab, 5'7\" bed", "1,820 lb", "1,840 lb", 1], ["3.0L Hurricane I6 twin turbo (SO)", "6,900/7,100 lb", "Crew Cab, 6'4\" bed", "1,730 lb", "1,750 lb", 1], ["5.7L HEMI V8", "6,900/7,100 lb", "Crew Cab, 5'7\" bed", "1,650 lb", "1,630 lb", 1], ["3.0L Hurricane I6 twin turbo H/O (RHO)", "Not stated", "Not stated", "NA", "1,490 lb", 1], ["3.0L Hurricane I6 twin turbo H/O (Limited)", "Not stated", "Not stated", "NA", "1,390 lb", 1]]}, "notes": ["Ram's conditions on the chart: \"When properly equipped.\" All weights are in pounds, rounded to the nearest 10 pounds, and trailer weight and payload ratings are mutually exclusive.", "The chart is titled Ram Tradesman 1500 (4x2/4x4); the Limited and RHO labels are printed in its High Output rows. The 3.6L V6 figure comes from the key features line of the same document, which names Quad Cab 4x2."]}], "check": ["Read the yellow Tire and Loading Information label on the driver's door jamb. It gives the combined weight of occupants and cargo your truck should never exceed.", "Add up passengers, cargo, accessories fitted after the truck was built and any trailer tongue weight, and keep the total under that label figure.", "A tonneau cover, bed rack or hitch counts against payload once it is on the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Ram, 2026 Ram 1500 payload and towing weight capacities chart", "https://www.ramtrucks.com/content/dam/fca-brands/na/ramtrucks/en_us/towing/towing-capacity-guide/brochure/26MY_Ram_1500_PayTow_2.3.pdf"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
