VALUES ('subaru', 'outback', 'cargo-space', $s$Subaru$s$, $s$Outback$s$, $s$Cargo space$s$, $s$Subaru Outback Cargo Space: 32.6 cu ft, 75.6 Folded (2025)$s$, $s$Subaru Outback Cargo Space: 32.6 / 75.6 cu ft (2025)$s$, $s$Subaru Outback cargo space from Subaru's 2025 spec comparison: 32.6 cubic feet behind the rear seat and 75.6 cubic feet with the rear seat lowered.$s$, $s$[{"q": "How much cargo space does a 2025 Subaru Outback have?", "a": "32.6 cubic feet with the rear seat up and 75.6 cubic feet with the rear seat lowered, by Subaru's 2025 trim comparison."}, {"q": "Is cargo space the same on the Wilderness?", "a": "Yes. Subaru prints 32.6 and 75.6 cubic feet for all nine 2025 trims, the Wilderness included."}]$s$::jsonb, $s${"answer": "The 2025 Subaru Outback has 32.6 cubic feet of cargo volume behind the rear seat and 75.6 cubic feet with the rear seat lowered, according to Subaru's trim comparison. The figures are the same on all nine trims.", "covers": "Model year 2025", "not_covered": "2020 to 2024 and the redesigned 2026 Outback: Subaru's figures for these years are not on this page yet.", "sections": [{"id": "cargo", "h": "Cargo volume (2025)", "table": {"head": ["Row in Subaru's comparison", "Figure", "Trims"], "rows": [["Cargo volume", "32.6 cubic feet", "All nine trims", 1], ["Maximum cargo volume", "75.6 cubic feet with rear seat lowered", "All nine trims", 1]]}, "notes": ["The nine trims are Base, Premium, Onyx Edition, Limited, Touring, Onyx Edition XT, Wilderness, Limited XT, Touring XT."]}], "check": ["The larger figure needs the rear seat lowered; with passengers in the back you have the smaller one.", "For a cargo box or a roof rack, the roof load limit matters, not the interior volume; look it up in your owner's manual.", "Always secure cargo and keep the total of passengers and cargo under the figure on the door jamb label.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "bike-racks"], "sources": [["Subaru, 2025 Outback Compare Specs (trim comparison)", "https://www.subaru.com/services/vehicles/pdf/trimComparison/2025/OBK"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
