VALUES ('subaru', 'outback', 'gas-tank-size', $s$Subaru$s$, $s$Outback$s$, $s$Gas tank size$s$, $s$Subaru Outback Gas Tank Size: 18.5 Gallons (2025)$s$, $s$Subaru Outback Gas Tank Size: 18.5 Gallons (2025)$s$, $s$Subaru Outback gas tank size from Subaru's 2025 spec comparison: 18.5 gallons on all nine trims, with the 2.5-liter or the 2.4-liter turbo engine.$s$, $s$[{"q": "How many gallons does a 2025 Subaru Outback hold?", "a": "18.5 gallons, by Subaru's 2025 trim comparison. It is listed as standard on all nine trims."}, {"q": "Do the XT and Wilderness have a different tank?", "a": "No. Subaru lists the 18.5-gallon tank for the turbocharged trims as well."}, {"q": "How far will a tank take me?", "a": "Multiply the tank size by the EPA figure on your window sticker for an estimate; the usable range is lower because you refuel before empty."}]$s$::jsonb, $s${"answer": "The 2025 Subaru Outback holds 18.5 gallons of fuel, according to Subaru's trim comparison. The tank is the same on all nine trims, with the 2.5-liter engine or the 2.4-liter turbocharged engine.", "covers": "Model year 2025", "not_covered": "2020 to 2024 and the redesigned 2026 Outback: Subaru's figures for these years are not on this page yet.", "sections": [{"id": "tank", "h": "Fuel tank capacity (2025)", "table": {"head": ["Trims", "Engine", "Fuel tank capacity"], "rows": [["Base, Premium, Onyx Edition, Limited, Touring", "2.5-liter SUBARU BOXER 4-cylinder", "18.5 gallons", 1], ["Onyx Edition XT, Wilderness, Limited XT, Touring XT", "2.4-liter turbocharged SUBARU BOXER 4-cylinder", "18.5 gallons", 1]]}}], "check": ["The pump may stop before or after the listed figure: the capacity is the tank's rated volume, not what fits after the low-fuel light.", "For range, multiply the tank size by the fuel economy on your window sticker and allow a margin, since you refuel before empty.", "A roof box or a trailer lowers fuel economy, so plan a shorter range when loaded.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "hitches"], "sources": [["Subaru, 2025 Outback Compare Specs (trim comparison)", "https://www.subaru.com/services/vehicles/pdf/trimComparison/2025/OBK"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
