VALUES ('subaru', 'outback', 'ground-clearance', $s$Subaru$s$, $s$Outback$s$, $s$Ground clearance$s$, $s$Subaru Outback Ground Clearance: 8.7 in, 9.5 in Wilderness (2025)$s$, $s$Subaru Outback Ground Clearance: 8.7 or 9.5 in (2025)$s$, $s$Subaru Outback ground clearance from Subaru's 2025 spec comparison: 8.7 inches on eight trims and 9.5 inches on the Wilderness, at base curb weight.$s$, $s$[{"q": "What is the ground clearance of a 2025 Subaru Outback?", "a": "8.7 inches, or 9.5 inches on the Wilderness, by Subaru's 2025 trim comparison. Subaru gives both at base curb weight."}, {"q": "How much ground clearance does the Outback Wilderness have?", "a": "9.5 inches at base curb weight."}, {"q": "Does Subaru list approach and departure angles?", "a": "Not in the part of the 2025 trim comparison that could be read for this page, so none are given here."}]$s$::jsonb, $s${"answer": "The 2025 Subaru Outback has 8.7 inches of ground clearance, and the Wilderness has 9.5 inches, according to Subaru's trim comparison. Subaru states both figures at base curb weight.", "covers": "Model year 2025", "not_covered": "2020 to 2024 and the redesigned 2026 Outback, and approach, departure and breakover angles.", "sections": [{"id": "clearance", "h": "Ground clearance at base curb weight (2025)", "table": {"head": ["Trims", "Ground clearance"], "rows": [["Base, Premium, Onyx Edition, Limited, Touring, Onyx Edition XT, Limited XT, Touring XT", "8.7 inches", 1], ["Wilderness", "9.5 inches", 1]]}, "notes": ["\"At base curb weight\" is Subaru's wording: the car sits lower with passengers and cargo on board."]}], "check": ["A loaded car sits lower than the listed figure, which Subaru gives at base curb weight.", "A hitch receiver or a low-hanging accessory can be the lowest point of the car.", "To measure your own Outback, park on level ground and measure from the ground to the lowest fixed point underneath.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "roof-racks", "floor-mats"], "sources": [["Subaru, 2025 Outback Compare Specs (trim comparison)", "https://www.subaru.com/services/vehicles/pdf/trimComparison/2025/OBK"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
