VALUES ('subaru', 'outback', 'tire-size', $s$Subaru$s$, $s$Outback$s$, $s$Tire size$s$, $s$Subaru Outback Tire Size: 225/65 R17 or 225/60 R18 (2025)$s$, $s$Subaru Outback Tire Size: 225/65 R17, 225/60 R18 (2025)$s$, $s$Subaru Outback tire sizes from Subaru's 2025 spec comparison: 225/65 R17 on Base, Premium and Wilderness, 225/60 R18 on the other six trims.$s$, $s$[{"q": "What size tires are on a 2025 Subaru Outback?", "a": "225/65 R17 on the Base, Premium and Wilderness, and 225/60 R18 on the other six trims, by Subaru's 2025 trim comparison."}, {"q": "What tires does the Outback Wilderness have?", "a": "225/65 R17 102T all-terrain tires on 17 x 7.0-inch matte black aluminum-alloy wheels, with a full-size spare."}, {"q": "Does the Outback have a full-size spare?", "a": "Subaru lists a full-size spare on the Onyx Edition XT and Wilderness, and a temporary T155/80 D17 spare on the other seven trims."}]$s$::jsonb, $s${"answer": "The 2025 Subaru Outback comes on 225/65 R17 tires as a Base, Premium or Wilderness and on 225/60 R18 tires on the other six trims, according to Subaru's trim comparison. The Wilderness tire is an all-terrain; the others are all-season.", "covers": "Model year 2025", "not_covered": "2020 to 2024 and the redesigned 2026 Outback, tire pressures, and the wheel bolt pattern.", "sections": [{"id": "tires", "h": "Tires and wheels by trim (2025)", "table": {"head": ["Trims", "Tire", "Wheel"], "rows": [["Base, Premium", "225/65 R17 102H all-season", "17 x 7.0-inch aluminum-alloy, black with machine finish", 1], ["Wilderness", "225/65 R17 102T all-terrain", "17 x 7.0-inch aluminum-alloy, matte black finish", 1], ["Onyx Edition, Onyx Edition XT", "225/60 R18 100H all-season", "18 x 7.0-inch aluminum-alloy, black finish", 1], ["Limited, Touring, Limited XT, Touring XT", "225/60 R18 100H all-season", "18 x 7.0-inch aluminum-alloy, black with machine finish", 1]]}}, {"id": "spare", "h": "Spare tire by trim (2025)", "table": {"head": ["Trims", "Spare"], "rows": [["Base, Premium, Onyx Edition, Limited, Touring, Limited XT, Touring XT", "Temporary use T155/80 D17 spare tire", 1], ["Onyx Edition XT, Wilderness", "Full-size spare tire", 1]]}}], "check": ["Read the size molded into the sidewall of the tires on your car: wheels and tires are often changed after purchase.", "The tire placard on the driver's door jamb gives the original tire size and cold inflation pressure.", "On an all-wheel-drive car, keep all four tires the same size and close in wear; see the owner's manual before replacing fewer than four.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["roof-racks", "floor-mats", "bike-racks"], "sources": [["Subaru, 2025 Outback Compare Specs (trim comparison)", "https://www.subaru.com/services/vehicles/pdf/trimComparison/2025/OBK"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
