VALUES ('subaru', 'outback', 'towing-capacity', $s$Subaru$s$, $s$Outback$s$, $s$Towing capacity$s$, $s$Subaru Outback Towing Capacity: 2,700 or 3,500 lb (2025)$s$, $s$Subaru Outback Towing Capacity: 2,700 or 3,500 lb (2025)$s$, $s$Subaru Outback towing capacity from Subaru's 2025 spec comparison: 2,700 lb with the 2.5-liter engine, 3,500 lb with the 2.4-liter turbo (XT, Wilderness).$s$, $s$[{"q": "How much can a 2025 Subaru Outback tow?", "a": "2,700 lb with the 2.5-liter engine and 3,500 lb with the 2.4-liter turbocharged engine, by Subaru's 2025 trim comparison."}, {"q": "How much can the Outback Wilderness tow?", "a": "Subaru lists a maximum towing capacity of 3,500 lbs. for the 2025 Outback Wilderness."}, {"q": "Which Outback trims tow 3,500 lb?", "a": "The Onyx Edition XT, Wilderness, Limited XT and Touring XT, all with the 2.4-liter turbocharged engine."}, {"q": "What is the Outback tongue weight limit?", "a": "Subaru's trim comparison does not print one in the part read for this page. Look it up in the towing section of your owner's manual."}]$s$::jsonb, $s${"answer": "The 2025 Subaru Outback tows a maximum of 2,700 lb with the 2.5-liter engine and 3,500 lb with the 2.4-liter turbocharged engine, according to Subaru's trim comparison. The turbocharged trims are the Onyx Edition XT, Wilderness, Limited XT and Touring XT.", "covers": "Model year 2025", "not_covered": "2020 to 2024 and the redesigned 2026 Outback. Tongue weight and the text of Subaru's footnote on the towing row are not on this page: they could not be read from the document.", "sections": [{"id": "towing", "h": "Maximum towing capacity by trim (2025)", "table": {"head": ["Trims", "Engine", "Maximum towing capacity"], "rows": [["Base, Premium, Onyx Edition, Limited, Touring", "2.5-liter SUBARU BOXER 4-cylinder", "2,700 lbs.", 1], ["Onyx Edition XT, Wilderness, Limited XT, Touring XT", "2.4-liter turbocharged SUBARU BOXER 4-cylinder", "3,500 lbs.", 1]]}, "notes": ["Subaru marks this row with a footnote. Read the towing section of the owner's manual for the equipment and loading conditions behind the figures."]}], "check": ["Find your trim on the window sticker: an XT or Wilderness badge means the turbocharged engine and the higher figure.", "Look up the tongue weight limit and the trailer brake requirements in your owner's manual before choosing a hitch.", "Read the labels on the driver's door jamb: passengers and cargo in the car count against what you can pull.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "bike-racks", "cargo-boxes"], "sources": [["Subaru, 2025 Outback Compare Specs (trim comparison)", "https://www.subaru.com/services/vehicles/pdf/trimComparison/2025/OBK"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
