VALUES ('tesla', 'model-y', 'cargo-space', $s$Tesla$s$, $s$Model Y$s$, $s$Cargo space$s$, $s$Tesla Model Y Cargo Space: 30.2 cu ft, 72.1 Folded (2020–2024)$s$, $s$Tesla Model Y Cargo Space: 30.2 / 72.1 cu ft (2020–2024)$s$, $s$Tesla Model Y cargo space from Tesla's 2020–2024 owner's manual: 30.2 cu ft behind the second row, 72.1 cu ft folded, plus a 4.1 cu ft front trunk.$s$, $s$[{"q": "How much cargo space does a Tesla Model Y have?", "a": "In the 5-seat 2020–2024 Model Y, Tesla's manual gives 30.2 cu ft behind the second row, 72.1 cu ft with the second row folded and 4.1 cu ft in the front trunk."}, {"q": "What is the total cargo volume of the Model Y?", "a": "Tesla prints a maximum total of 76.2 cu ft with only the driver and front passenger aboard, and 34.3 cu ft with five passengers, for the 5-seat car."}, {"q": "How much cargo space is behind the third row of a 7-seat Model Y?", "a": "12.8 cu ft (363 L), by Tesla's 2020–2024 manual. With the third row folded it is 26.6 cu ft."}]$s$::jsonb, $s${"answer": "The 2020–2024 Tesla Model Y with five seats has 30.2 cu ft of cargo volume behind the second row and 72.1 cu ft with the second row folded, plus a 4.1 cu ft front trunk, according to Tesla's owner's manual. The 7-seat version has 12.8 cu ft behind the third row.", "covers": "Model years 2020 to 2024", "not_covered": "2025 and later: the Dimensions page of Tesla's 2025+ manual could not be opened, so the refreshed Model Y is not on this page.", "sections": [{"id": "five-seat", "h": "Model Y with 5 seats (2020–2024)", "table": {"head": ["Area, as Tesla labels it", "Cargo volume"], "rows": [["Front trunk", "4.1 cu ft (117 L)", 1], ["Behind first row, second row seats folded", "72.1 cu ft (2,041 L)", 1], ["Behind second row, seats not folded", "30.2 cu ft (854 L)", 1], ["Maximum total cargo volume with driver and front passenger", "76.2 cu ft (2,158 L)", 1], ["Maximum total cargo volume with 5 passengers", "34.3 cu ft (971 L)", 1]]}}, {"id": "seven-seat", "h": "Model Y with 7 seats (2020–2024)", "table": {"head": ["Area, as Tesla labels it", "Cargo volume"], "rows": [["Front trunk", "4.1 cu ft (117 L)", 1], ["Behind first row, second and third row seats folded", "67.9 cu ft (1,923 L)", 1], ["Behind second row, third row seats folded", "26.6 cu ft (753 L)", 1], ["Behind third row", "12.8 cu ft (363 L)", 1], ["Maximum total cargo volume with driver and front passenger", "72 cu ft (2,040 L)", 1], ["Maximum total cargo volume with 7 passengers", "17 cu ft (480 L)", 1]]}, "notes": ["The totals add the front trunk to the rear cargo area: 72.1 + 4.1 = 76.2 cu ft in the 5-seat car."]}], "check": ["Count your seats first: the 5-seat and 7-seat cars have different figures.", "The folded figures need the rear seats lowered; with passengers in the back you have the smaller one.", "Volume is not a weight allowance: keep passengers and cargo under the figure on the door jamb label.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "floor-mats"], "sources": [["Tesla, Model Y Owner's Manual (2020–2024 edition, North America), Dimensions", "https://www.tesla.com/ownersmanual/2020_2024_modely/en_us/GUID-E47C4A6D-528E-419C-8C57-FD3864644C34.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
