VALUES ('tesla', 'model-y', 'ground-clearance', $s$Tesla$s$, $s$Model Y$s$, $s$Ground clearance$s$, $s$Tesla Model Y Ground Clearance: 6.8 in, 6.2 in Performance (2020–2024)$s$, $s$Tesla Model Y Ground Clearance: 6.8 in (2020–2024)$s$, $s$Tesla Model Y ground clearance from Tesla's 2020–2024 owner's manual: 6.8 in (172 mm), or 6.2 in (157 mm) for the Performance, with two passengers.$s$, $s$[{"q": "What is the ground clearance of a Tesla Model Y?", "a": "6.8 in (172 mm) for non-Performance versions and 6.2 in (157 mm) for the Performance, by Tesla's 2020–2024 owner's manual. Tesla measures it with two passengers aboard."}, {"q": "Is the Model Y Performance lower?", "a": "Yes. Tesla prints 6.2 in for the Performance against 6.8 in for the other versions, a difference of 0.6 in."}]$s$::jsonb, $s${"answer": "The 2020–2024 Tesla Model Y has 6.8 in (172 mm) of ground clearance, or 6.2 in (157 mm) in Performance form, according to Tesla's owner's manual. Tesla states both figures with two passengers in the car.", "covers": "Model years 2020 to 2024", "not_covered": "2025 and later: the Dimensions page of Tesla's 2025+ manual could not be opened, so the refreshed Model Y is not on this page.", "sections": [{"id": "clearance", "h": "Ground clearance (2020–2024)", "table": {"head": ["Version", "Ground clearance (with 2 passengers)"], "rows": [["Non-Performance", "6.8 in (172 mm)", 1], ["Performance", "6.2 in (157 mm)", 1]]}, "notes": ["Tesla's note on the table: values are approximate, and dimensions can vary depending on a vehicle's options and various other factors.", "Tesla does not split the figure by wheel size."]}], "check": ["A loaded car sits lower: Tesla's figure already includes two passengers, and more people or cargo reduce it further.", "Measure your own car on level ground at the lowest point under the body if you need an exact number for a ramp or a trail.", "Lowering springs or a different tire size change the figure.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "floor-mats", "roof-racks"], "sources": [["Tesla, Model Y Owner's Manual (2020–2024 edition, North America), Dimensions", "https://www.tesla.com/ownersmanual/2020_2024_modely/en_us/GUID-E47C4A6D-528E-419C-8C57-FD3864644C34.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
