INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('tesla', 'model-y', 'towing-capacity', $s$Tesla$s$, $s$Model Y$s$, $s$Towing capacity$s$, $s$Tesla Model Y Towing Capacity: Up to 3,500 lb (2025 and Later)$s$, $s$Tesla Model Y Towing Capacity: Up to 3,500 lb (2025+)$s$, $s$Tesla Model Y towing capacity from Tesla's 2025+ owner's manual: up to 3,500 lb and 350 lb tongue weight, less with more passengers in 6- and 7-seat cars.$s$, $s$[{"q": "How much can a Tesla Model Y tow?", "a": "Up to 3,500 lb with a 350 lb tongue weight, by Tesla's owner's manual for the 2025 and later Model Y. In the 6-seat and 7-seat versions the limit drops as passengers are added."}, {"q": "Does the number of passengers change the Model Y towing limit?", "a": "Yes in the 6-seat and 7-seat versions. Tesla's table for the 7-seater on 20-inch wheels goes from 3,500 lb with four or fewer people to 2,000 lb with six, and towing with seven is not permitted."}, {"q": "What size hitch receiver does the Model Y have?", "a": "Tesla's manual says the towing package includes a 2 in x 2 in hitch receiver. The package does not include a ball mount."}, {"q": "Does a Model Y trailer need its own brakes?", "a": "Tesla recommends a separate braking system with an independent controller for a trailer loaded to more than 1,650 lb (750 kg)."}]$s$::jsonb, $s${"answer": "The 2025 and later Tesla Model Y tows up to 3,500 lb with a maximum tongue weight of 350 lb, according to Tesla's owner's manual. The 5-seat and Performance versions keep that figure on every listed wheel size; the 6-seat and 7-seat versions are rated lower as passengers are added.", "covers": "Model year 2025 and later (the Model Y covered by Tesla's \"2025+\" owner's manual)", "not_covered": "2020 to 2024: the towing page of Tesla's 2020–2024 manual has not been read for this page yet. Two 6-seater rows for five passengers are left out because the manual prints two different figures for the same passenger count.", "sections": [{"id": "five-seat", "h": "5-seat and Performance", "table": {"head": ["Wheel size", "Passengers", "Maximum towing capacity", "Maximum tongue weight"], "rows": [["18 in", "5 or fewer", "3,500 lb (1,588 kg)", "350 lb (159 kg)", 1], ["19 in / 20 in", "5 or fewer", "3,500 lb (1,588 kg)", "350 lb (159 kg)", 1], ["21 in", "5 or fewer", "3,500 lb (1,588 kg)", "350 lb (159 kg)", 1]]}}, {"id": "six-seat", "h": "6-seat", "table": {"head": ["Wheel size", "Passengers", "Maximum towing capacity", "Maximum tongue weight"], "rows": [["19 in / 20 in", "4 or fewer", "3,500 lb", "350 lb (159 kg)", 1], ["19 in / 20 in", "6", "2,300 lb (1,043 kg)", "230 lb (104 kg)", 1]]}, "notes": ["Tesla prints two rows for five passengers in this table (3,400 lb and 2,850 lb) without saying what separates them, so they are not listed here."]}, {"id": "seven-seat", "h": "7-seat", "table": {"head": ["Wheel size", "Passengers", "Maximum towing capacity", "Maximum tongue weight"], "rows": [["19 in", "6 or fewer", "3,500 lb (1,588 kg)", "350 lb (159 kg)", 1], ["19 in", "7", "2,000 lb (907 kg)", "200 lb (91 kg)", 1], ["20 in", "4 or fewer", "3,500 lb (1,588 kg)", "350 lb (159 kg)", 1], ["20 in", "5 or fewer", "3,100 lb (1,406 kg)", "310 lb (141 kg)", 1], ["20 in", "6 or fewer", "2,000 lb (907 kg)", "200 lb (91 kg)", 1], ["20 in", "7", "Not permitted", "Not printed", 1]]}, "notes": ["Tesla: the maximum trailer weight, including all cargo and added equipment, and the tongue weight depend on the number of occupants and the tires being used.", "Tesla: tongue weight must not exceed 10% of the maximum trailer weight, and the towing capacity assumes the vehicle's GVWR is not exceeded.", "Tesla recommends a separate trailer braking system with an independent controller above 1,650 lb (750 kg) of trailer load.", "The towing package includes a 2 in x 2 in hitch receiver; used for an accessory carrier it supports vertical loads up to 160 lb (72 kg), carrier included."]}], "check": ["Count the seats and read the wheel size on your tire sidewall, then find your row above.", "Check that your Model Y has the tow package: Tesla warns against fitting a carrier to a Model Y without it.", "Tesla says its owner's manual takes precedence if the label on the hitch disagrees with it.", "Use a ball mount within Tesla's limits: up to 8.5 in long with a rise of up to 0.75 in.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "bike-racks", "cargo-boxes"], "sources": [["Tesla, Model Y Owner's Manual (2025+ edition, North America), Towing and Accessories", "https://www.tesla.com/ownersmanual/modely/en_us/GUID-F5C80FF5-8DE3-4750-8BAF-0DCC0CFA0C5C.html"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
