VALUES ('toyota', '4runner', 'cargo-space', $s$Toyota$s$, $s$4Runner$s$, $s$Cargo space$s$, $s$Toyota 4Runner Cargo Space: 47.2 cu ft, 89.7 Folded (2024)$s$, $s$Toyota 4Runner Cargo Space: 47.2 / 89.7 cu ft (2024)$s$, $s$Toyota 4Runner cargo space from Toyota's 2024 spec table: 47.2 cu ft behind the second row, 89.7 cu ft behind the front seats, less with a sliding deck.$s$, $s$[{"q": "How much cargo space does a 2024 Toyota 4Runner have?", "a": "47.2 cubic feet behind the second-row seats and 89.7 cubic feet behind the front seats, by Toyota's 2024 specification table."}, {"q": "Does the sliding cargo deck reduce cargo space?", "a": "Yes. With the sliding deck Toyota lists 46.3 cubic feet behind the second row and 88.8 behind the front seats."}, {"q": "How much room is behind the third row?", "a": "Toyota lists 9.0 cubic feet behind the third-row seats, on the grades it prints a third-row figure for."}]$s$::jsonb, $s${"answer": "The 2024 Toyota 4Runner has 47.2 cubic feet of cargo space behind the second-row seats and 89.7 cubic feet behind the front seats, according to Toyota's specification table. With the sliding rear cargo deck the figures are 46.3 and 88.8 cubic feet, and 9.0 cubic feet remain behind a third row.", "covers": "Model year 2024", "not_covered": "2010 to 2023, and the redesigned 2025 and 2026 4Runner. Which grades offer the third row is not on this page: Toyota prints the third-row figure in three of its seven grade columns, and they could not be matched to grades with certainty.", "sections": [{"id": "cargo", "h": "Interior cargo volume (2024)", "table": {"head": ["Row in Toyota's table", "Cargo volume", "Grade columns"], "rows": [["Behind front/second-row seats", "89.7/47.2 cu ft", "All seven: SR5, TRD Sport, SR5 Premium, TRD Off-Road, TRD Off-Road Premium, Limited and TRD Pro", 1], ["Behind front/second-row seats with sliding deck", "88.8/46.3 cu ft", "All seven", 1], ["Behind front/second/third-row seats", "88.8/46.3/9.0 cu ft", "Printed in three of the seven columns", 1]]}, "notes": ["Toyota's footnote on these figures: cargo and load capacity limited by weight and distribution."]}], "check": ["Check whether your 4Runner has the sliding rear cargo deck or a third row: both lower the figures.", "For a cargo box or a roof rack, the roof load limit matters, not the interior volume; look it up in your owner's manual.", "Always secure cargo and keep the total of passengers and cargo under the figure on the door jamb label.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["cargo-boxes", "roof-racks", "floor-mats"], "sources": [["Toyota, 2024 4Runner eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/4runner_ebrochure.pdf"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
