VALUES ('toyota', '4runner', 'tire-size', $s$Toyota$s$, $s$4Runner$s$, $s$Tire size$s$, $s$Toyota 4Runner Tire Size: P265/70R17 or P245/60R20 (2024)$s$, $s$Toyota 4Runner Tire Size: P265/70R17, P245/60R20 (2024)$s$, $s$Toyota 4Runner tire sizes from Toyota's 2024 brochure: P265/70R17 on SR5, TRD Off-Road and TRD Pro (all-terrain), P245/60R20 on the Limited.$s$, $s$[{"q": "What size tires are on a 2024 Toyota 4Runner?", "a": "P265/70R17 on the 17-inch wheels and P245/60R20 on the 20-inch wheels, by Toyota's 2024 brochure."}, {"q": "What size tires does the 4Runner TRD Pro have?", "a": "P265/70R17 all-terrain tires on TRD 17-inch matte-black alloy wheels."}, {"q": "What size tires does the 4Runner Limited have?", "a": "P245/60R20 tires on 20-inch split 6-spoke alloy wheels."}, {"q": "Does the 4Runner have a full-size spare?", "a": "Yes. Toyota's table lists a full-size spare tire, mounted under the body, as standard on all seven grades."}]$s$::jsonb, $s${"answer": "The 2024 Toyota 4Runner comes on P265/70R17 tires with its 17-inch wheels and P245/60R20 tires with its 20-inch wheels, according to Toyota's brochure. The SR5, TRD Off-Road and TRD Pro are listed with the 17-inch size, the Limited with the 20-inch size.", "covers": "Model year 2024", "not_covered": "2010 to 2023, the redesigned 2025 and 2026 4Runner, tire pressures and load ratings. The TRD Sport is left out: Toyota's grade page gives its 20-inch wheel but no tire size.", "sections": [{"id": "tires", "h": "Wheels and tires by grade, as Toyota lists them (2024)", "table": {"head": ["Grade page", "Wheel", "Tire"], "rows": [["SR5", "17-in. 6-spoke alloy wheels", "P265/70R17", 1], ["TRD Off-Road", "17-in. 7-spoke alloy wheels with black-painted accents", "P265/70R17", 1], ["Limited", "20-in. split 6-spoke alloy wheels", "P245/60R20", 1], ["TRD Pro", "TRD 17-in. matte-black alloy wheels", "P265/70R17 A/T", 1], ["All seven grades", "Spare", "Full-size spare tire, mounted under body", 1]]}, "notes": ["Toyota's features table repeats the same four wheel and tire lines for its seven grade columns; only the grades named on Toyota's own grade pages are shown here."]}], "check": ["Read the size molded into the sidewall of the tires on your vehicle: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Toyota, 2024 4Runner eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/4runner_ebrochure.pdf"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
