VALUES ('toyota', '4runner', 'towing-capacity', $s$Toyota$s$, $s$4Runner$s$, $s$Towing capacity$s$, $s$Toyota 4Runner Towing Capacity: 5,000 lb (2024), 6,000 lb (2025)$s$, $s$Toyota 4Runner Towing Capacity: 5,000 or 6,000 lb$s$, $s$Toyota 4Runner towing capacity from Toyota's own documents: 5,000 lb maximum for the 2024 model and 6,000 lb maximum for the redesigned 2025 model.$s$, $s$[{"q": "How much can a 2024 Toyota 4Runner tow?", "a": "Up to 5,000 lb. Toyota's 2024 brochure prints a \"5000-lb. max towing capacity\" for the 4Runner without splitting it by grade."}, {"q": "How much can a 2025 Toyota 4Runner tow?", "a": "Up to 6,000 lb. Toyota's release for the redesigned 2025 4Runner states a maximum towing capacity of 6,000 lbs."}, {"q": "Does every 2025 4Runner tow 6,000 lb?", "a": "Toyota's release gives 6,000 lb as the maximum and does not tie it to a grade or powertrain, so your grade may be rated lower."}, {"q": "What is the 4Runner tongue weight limit?", "a": "Neither document prints a tongue weight. Look it up in the towing section of your owner's manual."}]$s$::jsonb, $s${"answer": "The 2024 Toyota 4Runner tows up to 5,000 lb and the redesigned 2025 4Runner up to 6,000 lb, according to Toyota's brochure and press release. Both are maximum figures: neither document splits them by grade.", "covers": "Model years 2024 and 2025", "not_covered": "2010 to 2023 and 2026, towing by grade or powertrain, and tongue weight: Toyota's two documents print none of these.", "sections": [{"id": "towing", "h": "Maximum towing capacity Toyota states", "table": {"head": ["Model year", "Maximum towing capacity", "Applies to, as Toyota states it"], "rows": [["2024", "5,000 lb", "4Runner, no grade named", 1], ["2025", "6,000 lb", "4Runner, no grade or powertrain named", 2]]}, "notes": ["Toyota's 2024 footnote on towing: never tow beyond a vehicle's published towing capacities; the maximum depends on base curb weight plus the total weight of cargo, occupants and added equipment.", "The 2024 and 2025 4Runner are different generations, so one figure does not carry over to the other."]}], "check": ["Read the towing section of your owner's manual for the rating of your grade and for the tongue weight limit.", "Read the labels on the driver's door jamb: the trailer you can pull also depends on the weight of passengers and cargo in the vehicle.", "Match the hitch, ball mount and ball to the trailer weight; the lowest rating of the three is your limit.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "roof-racks", "cargo-boxes"], "sources": [["Toyota, 2024 4Runner eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/4runner_ebrochure.pdf"], ["Toyota Newsroom, The All-New 2025 Toyota 4Runner: The Icon That Inspires Exploration (10 Dec 2024)", "https://pressroom.toyota.com/?generate_pdf=97749"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-24', TIMESTAMPTZ '2026-11-24 10:00:00+06', 'model', '')
