VALUES ('toyota', 'highlander', 'ground-clearance', $s$Toyota$s$, $s$Highlander$s$, $s$Ground clearance$s$, $s$Toyota Highlander Ground Clearance: 8 Inches (2024)$s$, $s$Toyota Highlander Ground Clearance: 8 in (2024)$s$, $s$Toyota Highlander ground clearance from Toyota's 2024 brochure: 8 inches on every gas and hybrid grade, from LE to Platinum.$s$, $s$[{"q": "What is the ground clearance of a 2024 Toyota Highlander?", "a": "8 inches, by Toyota's 2024 brochure. The same figure is printed for all eleven gas and hybrid grades."}, {"q": "Does the Highlander Hybrid sit lower?", "a": "Not by Toyota's 2024 figures: hybrid and gas grades are both listed at 8 inches."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Highlander has 8 inches of ground clearance on every grade, gas and hybrid, according to Toyota's brochure.", "covers": "Model year 2024", "not_covered": "2020 to 2023, 2025 and 2026: Toyota's 2026 brochure prints no ground clearance, and the other years are not on this page yet.", "sections": [{"id": "clearance", "h": "Ground clearance (2024)", "table": {"head": ["Grades", "Ground clearance"], "rows": [["Gas: LE, XLE, XSE, Limited, Platinum", "8 in", 1], ["Hybrid LE, Hybrid LE Nightshade, Hybrid XLE, Hybrid XLE Nightshade, Hybrid Limited, Hybrid Platinum", "8 in", 1]]}, "notes": ["Toyota prints the figure as a whole number, 8, without a decimal."]}], "check": ["A loaded vehicle sits lower than the published figure.", "Measure your own vehicle on level ground at the lowest point under the body if you need an exact number.", "A different tire size or a lift kit changes the figure.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Toyota, 2024 Highlander eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/highlander_ebrochure.pdf"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
