VALUES ('toyota', 'highlander', 'tire-size', $s$Toyota$s$, $s$Highlander$s$, $s$Tire size$s$, $s$Toyota Highlander Tire Size: P235/65R18 or P235/55R20 (2024, 2026)$s$, $s$Toyota Highlander Tire Size: P235/65R18, P235/55R20$s$, $s$Toyota Highlander tire size from Toyota's 2024 and 2026 brochures: P235/65R18 with 18-inch wheels and P235/55R20 with 20-inch wheels, listed by grade.$s$, $s$[{"q": "What size tires are on a Toyota Highlander?", "a": "P235/65R18 on grades with 18-inch wheels and P235/55R20 on grades with 20-inch wheels, by Toyota's 2024 and 2026 brochures."}, {"q": "Which Highlander grades have 20-inch tires?", "a": "XSE, Limited, Platinum, Hybrid Limited and Hybrid Platinum, in both the 2024 and 2026 brochures."}, {"q": "Does the Highlander have a full-size spare?", "a": "Toyota's 2024 brochure lists a temporary spare tire as standard on all eleven grades."}]$s$::jsonb, $s${"answer": "The Toyota Highlander uses P235/65R18 tires on grades with 18-inch wheels and P235/55R20 tires on grades with 20-inch wheels, according to Toyota's 2024 and 2026 brochures. XSE, Limited and Platinum grades get the 20-inch size.", "covers": "Model years 2024 and 2026", "not_covered": "2020 to 2023 and 2025, the wheel bolt pattern, tire pressures and load ratings: Toyota's brochures print none of these.", "sections": [{"id": "y2024", "h": "2024 Highlander", "table": {"head": ["Wheel, as Toyota describes it", "Tire size", "Grades"], "rows": [["18-in. painted alloy wheels", "P235/65R18", "LE, Hybrid LE", 1], ["18-in. machined-finish alloy wheels", "P235/65R18", "XLE, Hybrid XLE", 1], ["18-in. black alloy wheels", "P235/65R18", "Hybrid LE Nightshade, Hybrid XLE Nightshade", 1], ["20-in. black alloy wheels", "P235/55R20", "XSE", 1], ["20-in. chrome-finished wheels", "P235/55R20", "Limited, Hybrid Limited", 1], ["20-in. alloy wheels", "P235/55R20", "Platinum, Hybrid Platinum", 1]]}, "notes": ["Toyota lists all-season tires and a temporary spare tire as standard on all eleven 2024 grades."]}, {"id": "y2026", "h": "2026 Highlander", "table": {"head": ["Wheel, as Toyota describes it", "Tire size", "Grades"], "rows": [["18-in. machined-finished alloy wheels", "P235/65R18", "Two grades; the grade names could not be matched in the brochure table", 2], ["20-in. black alloy wheels", "P235/55R20", "XSE", 2], ["20-in. chrome-finished alloy wheels", "P235/55R20", "Limited, Hybrid Limited", 2], ["20-in. alloy wheels", "P235/55R20", "Platinum, Hybrid Platinum", 2]]}, "notes": ["The 2026 lineup is XLE, XSE, Limited, Platinum, Hybrid XLE, Hybrid Limited and Hybrid Platinum."]}], "check": ["Read the tire and loading label on the driver's door jamb: it names the original size and pressure for your vehicle.", "Compare it with the size on your tire sidewall; a previous owner may have changed it.", "Keep the load index and speed rating at or above the original when you replace tires.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "floor-mats", "running-boards"], "sources": [["Toyota, 2024 Highlander eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/highlander_ebrochure.pdf"], ["Toyota, 2026 Highlander brochure", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2026/2026-highlander-brochure.pdf"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
