VALUES ('toyota', 'highlander', 'towing-capacity', $s$Toyota$s$, $s$Highlander$s$, $s$Towing capacity$s$, $s$Toyota Highlander Towing Capacity: 5,000 lb Gas, 3,500 lb Hybrid$s$, $s$Toyota Highlander Towing Capacity: 5,000 / 3,500 lb$s$, $s$Toyota Highlander towing capacity from Toyota's brochures: 5,000 lb for 2024 gas grades, 3,500 lb for 2024 hybrids, up to 5,000 lb for the 2026 gas engine.$s$, $s$[{"q": "How much can a Toyota Highlander tow?", "a": "5,000 lb for the 2024 gas grades and 3,500 lb for the 2024 hybrid grades, by Toyota's 2024 brochure. The 2026 brochure states up to 5,000 lb for the 2.4-liter turbo gas engine."}, {"q": "How much can a Highlander Hybrid tow?", "a": "3,500 lb for all six 2024 hybrid grades. Toyota's 2026 brochure does not print a hybrid towing figure."}, {"q": "Is the towing figure the same on every gas grade?", "a": "For 2024, yes: Toyota prints 5,000 lb for LE, XLE, XSE, Limited and Platinum."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Highlander tows 5,000 lb with the gas engine and 3,500 lb as a hybrid, according to Toyota's brochure. For 2026 Toyota states up to 5,000 lb for the 2.4-liter turbo gas engine and prints no hybrid figure.", "covers": "Model years 2024 and 2026", "not_covered": "2020 to 2023 and 2025, the 2026 hybrid figure, and tongue weight: these are not in the two Toyota brochures read for this page.", "sections": [{"id": "towing", "h": "Towing capacity Toyota states", "table": {"head": ["Model year", "Towing capacity", "Applies to, as Toyota states it"], "rows": [["2024", "5,000 lb", "Gas grades: LE, XLE, XSE, Limited, Platinum", 1], ["2024", "3,500 lb", "Hybrid LE, Hybrid LE Nightshade, Hybrid XLE, Hybrid XLE Nightshade, Hybrid Limited, Hybrid Platinum", 1], ["2026", "Up to 5,000 lb", "2.4-liter turbo gas engine, no grade named", 2]]}, "notes": ["Toyota's 2024 footnote on towing: never tow beyond a vehicle's published towing capacities; the maximum depends on base curb weight plus the total weight of cargo, occupants and added equipment.", "Toyota's brochures add: before towing, confirm the Stop and Start Engine System is disengaged."]}], "check": ["Confirm whether your Highlander is gas or hybrid; the 2024 ratings differ by 1,500 lb.", "Read the towing section of your owner's manual for the tongue weight limit and the equipment Toyota requires.", "Match the hitch, ball mount and ball to the trailer weight; the lowest rating of the three is your limit.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "bike-racks", "cargo-boxes"], "sources": [["Toyota, 2024 Highlander eBrochure, specifications and features tables", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/highlander_ebrochure.pdf"], ["Toyota, 2026 Highlander brochure", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2026/2026-highlander-brochure.pdf"]], "reviewed": "2026-11-23"}$s$::jsonb, 'published', DATE '2026-11-25', TIMESTAMPTZ '2026-11-25 10:00:00+06', 'model', '')
