INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('toyota', 'tacoma', 'bed-dimensions', $s$Toyota$s$, $s$Tacoma$s$, $s$Bed dimensions$s$, $s$Toyota Tacoma Bed Size: 5-ft and 6-ft Bed Dimensions (2024)$s$, $s$Toyota Tacoma Bed Size: 5-ft and 6-ft Dimensions (2024)$s$, $s$Toyota Tacoma bed size from Toyota's 2024 spec table: 60.3 in (5-ft bed) or 73.5 in (6-ft bed) long inside, 44.7 in between the wheelwells.$s$, $s$[{"q": "How long is a Toyota Tacoma bed?", "a": "Toyota's 2024 table lists an inside bed length of 60.3 inches for the 5-ft bed and 73.5 inches for the 6-ft bed."}, {"q": "How wide is a Tacoma bed between the wheel wells?", "a": "44.7 inches. Toyota also lists 53 inches at the tailgate and 56.4 inches at the accessory rail, the same for every cab and grade."}, {"q": "How deep is a Tacoma bed?", "a": "Toyota lists an inside bed depth of 20.2 inches on 4x2 trucks and 21.2 inches on 4x4 trucks."}, {"q": "Which Tacoma has the 6-ft bed?", "a": "Toyota's launch release says the XtraCab comes exclusively with a six-foot bed, and that the two cab styles are offered with either a five- or six-foot bed. Check the build of the truck you are looking at."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tacoma bed is 60.3 inches long inside as a 5-ft bed and 73.5 inches as a 6-ft bed, according to Toyota's specification table. Both are 44.7 inches wide between the wheelwells and 20.2 inches (4x2) or 21.2 inches (4x4) deep.", "covers": "Model year 2024", "not_covered": "2016 to 2023, 2025 and 2026. Which grade can be ordered with which bed is not on this page: the two readings of Toyota's table did not settle it.", "sections": [{"id": "bed", "h": "Inside bed dimensions (2024)", "table": {"head": ["Measurement", "5-ft bed", "6-ft bed"], "rows": [["Inside bed length", "60.3 in", "73.5 in", 1], ["Inside bed width, at tailgate", "53 in", "53 in", 1], ["Inside bed width, at accessory rail", "56.4 in", "56.4 in", 1], ["Inside bed width, between wheelwells", "44.7 in", "44.7 in", 1], ["Inside bed depth, 4x2", "20.2 in", "20.2 in", 1], ["Inside bed depth, 4x4", "21.2 in", "21.2 in", 1], ["Offered on the XtraCab", "No", "Yes (six-foot bed only)", 2]]}, "notes": ["Toyota prints the widths and depths once per grade, not per bed length; they are the same in every column of its table."]}], "check": ["Measure your own bed from the inside of the bulkhead to the inside of the closed tailgate: 60.3 inches is the 5-ft bed, 73.5 inches the 6-ft bed.", "Buy tonneau covers and bed racks by the bed length, not by the cab name.", "For anything that sits between the wheelwells, 44.7 inches is the limit.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Toyota, 2024 Tacoma eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tacoma_ebrochure.pdf"], ["Toyota Newsroom, All-New 2024 Toyota Tacoma is Adventure Ready Out of the Box (28 Nov 2023)", "https://pressroom.toyota.com/all-new-2024-toyota-tacoma-is-adventure-ready-out-of-the-box/"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-22', TIMESTAMPTZ '2026-11-22 10:00:00+06', 'model', '')
