VALUES ('toyota', 'tacoma', 'tire-size', $s$Toyota$s$, $s$Tacoma$s$, $s$Tire size$s$, $s$Toyota Tacoma Tire Size by Wheel and Grade (2024)$s$, $s$Toyota Tacoma Tire Size by Wheel and Grade (2024)$s$, $s$Toyota Tacoma tire sizes from Toyota's 2024 brochure: 245/70R17, 265/70R17, 265/65R18 and 265/70R18, plus 33-in tires on Trailhunter and TRD Pro.$s$, $s$[{"q": "What size tires come on a 2024 Toyota Tacoma?", "a": "Toyota's 2024 brochure lists 245/70R17 with the 17-inch steel and styled alloy wheels, 265/70R17 all-terrain on the TRD PreRunner and 265/65R18 on the Limited."}, {"q": "What tires are on the TRD Pro and Trailhunter?", "a": "Toyota describes both with 18-inch wheels and 33-inch Goodyear Territory R/T tires. The brochure does not print a metric size for them."}, {"q": "What size tires does the TRD Off-Road have?", "a": "Toyota lists 18-inch TRD Off-Road alloy wheels with 265/70R18 all-terrain tires as available. The line for the standard TRD Off-Road wheel is left off this page because its wheel and tire sizes do not match in Toyota's print."}, {"q": "Where do I find the tire pressure?", "a": "On the Tire and Loading Information label on the driver's door jamb. The brochure prints sizes only."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tacoma comes on 245/70R17 tires with the 17-inch steel or styled alloy wheels, 265/70R17 all-terrain tires as a TRD PreRunner and 265/65R18 tires as a Limited, according to Toyota's brochure. Trailhunter and TRD Pro wear 33-inch Goodyear Territory R/T tires.", "covers": "Model year 2024", "not_covered": "2016 to 2023, 2025 and 2026, tire pressures and load ratings. The TRD Sport line and the standard TRD Off-Road line are left out: in Toyota's brochure the wheel diameter and the tire size on those lines do not match.", "sections": [{"id": "tires", "h": "Tires by wheel, as Toyota lists them (2024)", "table": {"head": ["Tire", "Wheel line in Toyota's brochure"], "rows": [["245/70R17", "17-in. steel wheels", 1], ["245/70R17", "17-in. styled alloy wheels", 1], ["265/70R17 all-terrain", "17-in. TRD PreRunner alloy wheels", 1], ["265/65R18", "18-in. Limited chrome-finished alloy wheels", 1], ["265/70R18 all-terrain", "18-in. TRD Off-Road alloy wheels (marked available)", 1], ["33-in. Goodyear Territory R/T", "18-in. Trailhunter bronze-finished alloy wheels", 1], ["33-in. Goodyear Territory R/T", "18-in. TRD Pro black alloy wheels", 1]]}, "notes": ["The steel and styled alloy wheel lines do not name a grade. Toyota's table marks them standard on some grades, but the grade columns could not be read with certainty, so no grade is given here."]}], "check": ["Read the size molded into the sidewall of the tires on your truck: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure for your truck.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Toyota, 2024 Tacoma eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tacoma_ebrochure.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
