INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('toyota', 'tundra', 'bed-dimensions', $s$Toyota$s$, $s$Tundra$s$, $s$Bed dimensions$s$, $s$Toyota Tundra Bed Size: 5.5-ft, 6.5-ft and 8.1-ft Beds (2024)$s$, $s$Toyota Tundra Bed Size: 5.5, 6.5 and 8.1-ft Beds (2024)$s$, $s$Toyota Tundra bed size from Toyota's 2024 spec table: 65.6, 77.6 or 96.5 in long inside, 48.7 in between the wheelwells, 20.9 in deep.$s$, $s$[{"q": "How long is a Toyota Tundra bed?", "a": "Toyota's 2024 table lists an inside bed length of 65.6 inches for the 5.5-ft short bed, 77.6 inches for the 6.5-ft standard bed and 96.5 inches for the 8.1-ft long bed."}, {"q": "How wide is a Tundra bed between the wheel wells?", "a": "48.7 inches, with an inside bed width of 58.7 inches. Toyota prints the same widths for every cab and bed."}, {"q": "How deep is a Tundra bed?", "a": "20.9 inches, the same for every cab and bed in Toyota's 2024 table."}, {"q": "Which cab gets which bed?", "a": "Toyota lists the Double Cab with the 6.5-ft or 8.1-ft bed and the CrewMax with the 5.5-ft or 6.5-ft bed."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tundra bed is 65.6 inches long inside as the 5.5-ft bed, 77.6 inches as the 6.5-ft bed and 96.5 inches as the 8.1-ft bed, according to Toyota's specification table. Every bed is 58.7 inches wide, 48.7 inches between the wheelwells and 20.9 inches deep.", "covers": "Model year 2024", "not_covered": "2022, 2023, 2025 and 2026, and the earlier generation: Toyota's tables for these years are not on this page yet.", "sections": [{"id": "bed", "h": "Inside bed dimensions by cab and bed (2024)", "table": {"head": ["Measurement", "Double Cab, 6.5-ft bed", "Double Cab, 8.1-ft bed", "CrewMax, 5.5-ft bed", "CrewMax, 6.5-ft bed"], "rows": [["Inside bed length", "77.6 in", "96.5 in", "65.6 in", "77.6 in", 1], ["Inside bed width", "58.7 in", "58.7 in", "58.7 in", "58.7 in", 1], ["Inside bed width between wheelwells", "48.7 in", "48.7 in", "48.7 in", "48.7 in", 1], ["Inside bed depth", "20.9 in", "20.9 in", "20.9 in", "20.9 in", 1]]}, "notes": ["Toyota names the beds 5.5-ft Short Bed, 6.5-ft Standard Bed and 8.1-ft Long Bed."]}], "check": ["Measure your own bed from the inside of the bulkhead to the inside of the closed tailgate and match it to 65.6, 77.6 or 96.5 inches.", "Buy tonneau covers and bed racks by the bed length, not by the cab name: the 6.5-ft bed comes on both cabs.", "For anything that sits between the wheelwells, 48.7 inches is the limit.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Toyota, 2024 Tundra eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tundra_ebrochure.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
