VALUES ('toyota', 'tundra', 'ground-clearance', $s$Toyota$s$, $s$Tundra$s$, $s$Ground clearance$s$, $s$Toyota Tundra Ground Clearance: 9.3 in Gas, 8.5 in Hybrid (2024)$s$, $s$Toyota Tundra Ground Clearance: Gas and Hybrid (2024)$s$, $s$Toyota Tundra ground clearance from Toyota's 2024 spec table: minimum 9.3 in with the gas engine and 8.5 in with the hybrid, plus approach angles.$s$, $s$[{"q": "What is the ground clearance of a 2024 Toyota Tundra?", "a": "Toyota's 2024 table lists a minimum ground clearance of 9.3 inches for gas trucks and 8.5 inches for hybrids."}, {"q": "Why is the hybrid lower?", "a": "Toyota's table does not say. It prints 8.5 inches in the hybrid row and 9.3 inches in the gas row."}, {"q": "What are the approach and departure angles?", "a": "Toyota prints 21.0/24.0 for approach/departure in every cab and bed column, and 26.2/24.2 for the TRD Pro."}, {"q": "Does Toyota publish a breakover angle?", "a": "Not in the 2024 brochure: it has no breakover row."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tundra has a minimum ground clearance of 9.3 inches with the gas engine and 8.5 inches with the hybrid, according to Toyota's specification table. Toyota prints approach and departure angles of 21.0 and 24.0, or 26.2 and 24.2 on the TRD Pro.", "covers": "Model year 2024", "not_covered": "2022, 2023, 2025 and 2026, and the earlier generation. Toyota's table gives no ground clearance by grade and no breakover angle.", "sections": [{"id": "clearance", "h": "Minimum ground clearance and angles (2024)", "table": {"head": ["Measurement", "Figure", "Applies to"], "rows": [["Minimum ground clearance, gas", "9.3 in", "All four cab and bed combinations", 1], ["Minimum ground clearance, hybrid", "8.5 in", "Hybrid trucks", 1], ["Approach/departure angle", "21.0/24.0", "All four cab and bed combinations", 1], ["Approach/departure angle", "26.2/24.2", "TRD Pro", 1]]}, "notes": ["Toyota prints the angles as bare numbers, without a unit, under an off-highway heading."]}], "check": ["Check whether your truck is a hybrid (i-FORCE MAX): the hybrid row is lower.", "The figures are for an unmodified truck. Running boards, a hitch or a front air dam can sit lower than the listed clearance point.", "To measure your own truck, park on level ground and measure from the ground to the lowest fixed point under the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "hitches"], "sources": [["Toyota, 2024 Tundra eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tundra_ebrochure.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
