INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('toyota', 'tundra', 'payload-capacity', $s$Toyota$s$, $s$Tundra$s$, $s$Payload capacity$s$, $s$Toyota Tundra Payload Capacity by Grade and Cab (2024)$s$, $s$Toyota Tundra Payload Capacity by Grade and Cab (2024)$s$, $s$Toyota Tundra payload capacity from Toyota's 2024 spec table: up to 1,940 lb (SR and SR5 4x2), 1,485 to 1,680 lb for i-FORCE MAX hybrids.$s$, $s$[{"q": "What is the payload capacity of a 2024 Toyota Tundra?", "a": "Up to 1,940 lb. Toyota's 2024 table prints that figure for the SR and for the SR5 Double Cab with the 6.5-ft bed, both 4x2."}, {"q": "How much payload does the Tundra hybrid have?", "a": "Toyota lists the i-FORCE MAX hybrid between 1,485 lb (Capstone) and 1,680 lb (Limited 4x2). The TRD Pro is listed at 1,600 lb."}, {"q": "Does payload include passengers?", "a": "Yes. Toyota's footnote says payload includes the weight of occupants, cargo and options and is limited by weight distribution."}, {"q": "Where is the payload for my own Tundra?", "a": "On the Tire and Loading Information label on the driver's door jamb. The brochure figure is a maximum for the configuration; options on your truck reduce it."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tundra carries a maximum payload of up to 1,940 lb, a figure Toyota lists for the SR and SR5 with 4x2. The other grades are lower, and the i-FORCE MAX hybrids are listed at 1,485 to 1,680 lb.", "covers": "Model year 2024", "not_covered": "2022, 2023, 2025 and 2026, and the earlier generation. For grades other than SR5, Toyota's table leaves some cab and bed cells blank, so this page gives the range printed for the grade instead of a figure per cab.", "sections": [{"id": "sr5", "h": "SR5, i-FORCE 3.4L twin-turbo V6, by cab and bed (2024)", "table": {"head": ["Drivetrain", "Double Cab, 6.5-ft bed", "Double Cab, 8.1-ft bed", "CrewMax, 5.5-ft bed", "CrewMax, 6.5-ft bed"], "rows": [["4x2", "1,940 lb", "1,875 lb", "1,830 lb", "1,810 lb", 1], ["4x4", "1,885 lb", "1,810 lb", "1,820 lb", "1,720 lb", 1]]}}, {"id": "grades", "h": "Other grades: maximum payload printed for the grade (2024)", "intro": "Where Toyota prints more than one figure for a grade, the lowest and highest are shown. A dash means Toyota lists no figure.", "table": {"head": ["Grade", "Powertrain", "4x2", "4x4"], "rows": [["SR", "i-FORCE", "1,810 to 1,940 lb", "1,810 to 1,885 lb", 1], ["Limited", "i-FORCE", "1,700 to 1,860 lb", "1,645 to 1,820 lb", 1], ["Platinum", "i-FORCE", "1,630 to 1,720 lb", "1,575 to 1,665 lb", 1], ["1794 Edition", "i-FORCE", "1,630 to 1,720 lb", "1,575 to 1,665 lb", 1], ["Limited", "i-FORCE MAX hybrid", "1,665 to 1,680 lb", "1,605 to 1,665 lb", 1], ["Platinum", "i-FORCE MAX hybrid", "1,640 to 1,655 lb", "1,565 to 1,595 lb", 1], ["1794 Edition", "i-FORCE MAX hybrid", "1,640 to 1,655 lb", "1,565 to 1,595 lb", 1], ["TRD Pro", "i-FORCE MAX hybrid", "—", "1,600 lb", 1], ["Capstone", "i-FORCE MAX hybrid", "—", "1,485 lb", 1]]}, "notes": ["Toyota's footnote on these figures: payload includes the weight of occupants, cargo and options and is limited by weight distribution."]}], "check": ["Read the yellow Tire and Loading Information label on the driver's door jamb. It gives the combined weight of occupants and cargo your truck should never exceed.", "Add up passengers, cargo, accessories fitted after the truck was built and any trailer tongue weight, and keep the total under that label figure.", "A tonneau cover, bed rack or hitch counts against payload once it is on the truck.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["tonneau-covers", "bed-racks", "hitches"], "sources": [["Toyota, 2024 Tundra eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tundra_ebrochure.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
