INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('toyota', 'tundra', 'tire-size', $s$Toyota$s$, $s$Tundra$s$, $s$Tire size$s$, $s$Toyota Tundra Tire Size: 245/75R18 to 265/50R22 (2024)$s$, $s$Toyota Tundra Tire Size: 18, 20 and 22 Inch (2024)$s$, $s$Toyota Tundra tire sizes from Toyota's 2024 spec table: 245/75R18, 265/70R18, 265/60R20, 265/50R22 and the 285/65R18 all-terrain tire of the TRD Pro.$s$, $s$[{"q": "What size tires are on a 2024 Toyota Tundra?", "a": "Toyota's 2024 table lists 245/75R18, 265/70R18, 265/60R20 and 265/50R22 all-season tires, plus all-terrain tires in 265/70R18, 265/60R20 and 285/65R18."}, {"q": "What size tires does the Tundra TRD Pro have?", "a": "Toyota lists 285/65R18 Falken WILDPEAK all-terrain tires for the TRD Pro, on 18-inch forged-aluminum BBS wheels."}, {"q": "What tires come with the TRD Off-Road Package?", "a": "Toyota lists 265/70R18 Michelin LTX Trail all-terrain tires and 265/60R20 Falken WILDPEAK all-terrain tires under the TRD Off-Road Package, depending on wheel size."}, {"q": "Which Tundra has 22-inch tires?", "a": "Toyota lists one 22-inch tire, 265/50R22, and its grade pages list 22-inch wheels for the Capstone."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tundra comes on 245/75R18, 265/70R18, 265/60R20 or 265/50R22 all-season tires, according to Toyota's specification table. The TRD Off-Road Package brings 265/70R18 or 265/60R20 all-terrain tires, and the TRD Pro wears 285/65R18 all-terrain tires.", "covers": "Model year 2024", "not_covered": "2022, 2023, 2025 and 2026, the earlier generation, tire pressures and load ratings. For most lines the grade is not named: the marks in Toyota's table could not be matched to its grade columns with certainty.", "sections": [{"id": "tires", "h": "Tire lines in Toyota's table (2024)", "table": {"head": ["Tire, as Toyota prints it", "Marks in Toyota's table", "What Toyota ties it to"], "rows": [["245/75R18 all-season", "Standard in one grade column", "Listed with the 18-in. styled-steel wheels; the SR grade page lists 18-in. styled-steel wheels", 1], ["265/70R18 all-season", "Standard in one grade column", "Not stated on the line", 1], ["265/60R20 all-season", "Package in one grade column, standard in three", "Not stated on the line", 1], ["265/50R22 all-season", "Standard in one grade column", "The Capstone grade page lists 22-in. wheels", 1], ["265/70R18 Michelin LTX Trail all-terrain", "Package in one grade column", "TRD Off-Road Package", 1], ["265/60R20 Falken WILDPEAK all-terrain", "Package in three grade columns", "TRD Off-Road Package", 1], ["285/65R18 Falken WILDPEAK all-terrain", "Standard in one grade column", "TRD Pro", 1], ["Spare", "Standard in all seven grade columns", "Full-size, mounted under body", 1]]}, "notes": ["Toyota prints the first size as P245/75R18 on its wheel line and 245/75R18 on its tire line, and the TRD Pro size as P285/65R18 on the grade page and 285/65R18 in the table."]}], "check": ["Read the size molded into the sidewall of the tires on your truck: wheels and tires are often changed after purchase.", "The Tire and Loading Information label on the driver's door jamb gives the original tire size and cold inflation pressure for your truck.", "When you replace tires, match the load index and speed rating on that label or in the owner's manual, especially if you tow.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["lift-kits", "running-boards", "floor-mats"], "sources": [["Toyota, 2024 Tundra eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tundra_ebrochure.pdf"]], "reviewed": "2026-11-22"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
