INSERT INTO spec_pages (make_slug, model_slug, topic, make_name, model_name, topic_label, title, seo_title, meta_desc, faq, page, status, published_at, publish_at, kind, gen_slug)
VALUES ('toyota', 'tundra', 'towing-capacity', $s$Toyota$s$, $s$Tundra$s$, $s$Towing capacity$s$, $s$Toyota Tundra Towing Capacity by Grade and Cab (2024)$s$, $s$Toyota Tundra Towing Capacity by Grade and Cab (2024)$s$, $s$Toyota Tundra towing capacity from Toyota's 2024 spec table: up to 12,000 lb (SR5 Double Cab 4x2), 8,300 lb for SR, 10,340 to 11,450 lb for the hybrid.$s$, $s$[{"q": "How much can a 2024 Toyota Tundra tow?", "a": "Up to 12,000 lb. Toyota's 2024 table prints that figure for the SR5 Double Cab with the 6.5-ft bed, the i-FORCE engine and 4x2. The SR is listed at 8,300 lb."}, {"q": "How much can the Tundra hybrid tow?", "a": "Toyota lists the i-FORCE MAX hybrid between 10,340 lb (Capstone) and 11,450 lb (Limited 4x2). The TRD Pro is listed at 11,175 lb."}, {"q": "Does 4x4 lower the towing capacity?", "a": "In Toyota's SR5 rows, yes: each 4x4 figure is lower than the 4x2 figure for the same cab and bed. The SR5 Double Cab 6.5-ft bed drops from 12,000 lb to 11,200 lb."}, {"q": "Is the towing capacity on this page the limit for my truck?", "a": "No. It is the figure Toyota published for that configuration. The limit for your truck is on its door-jamb labels and in its owner's manual, and it drops with passengers and cargo on board."}]$s$::jsonb, $s${"answer": "The 2024 Toyota Tundra tows up to 12,000 lb, a figure Toyota lists for the SR5 Double Cab with the 6.5-ft bed and 4x2. The SR is rated at 8,300 lb, the other i-FORCE grades at 10,890 to 11,400 lb and the i-FORCE MAX hybrids at 10,340 to 11,450 lb.", "covers": "Model year 2024", "not_covered": "2022, 2023, 2025 and 2026, and the earlier generation. For grades other than SR5, Toyota's table leaves some cab and bed cells blank, so this page gives the range printed for the grade instead of a figure per cab.", "sections": [{"id": "sr5", "h": "SR5, i-FORCE 3.4L twin-turbo V6, by cab and bed (2024)", "table": {"head": ["Drivetrain", "Double Cab, 6.5-ft bed", "Double Cab, 8.1-ft bed", "CrewMax, 5.5-ft bed", "CrewMax, 6.5-ft bed"], "rows": [["4x2", "12,000 lb", "11,370 lb", "11,400 lb", "11,270 lb", 1], ["4x4", "11,200 lb", "11,090 lb", "11,160 lb", "11,010 lb", 1]]}}, {"id": "grades", "h": "Other grades: maximum towing printed for the grade (2024)", "intro": "Where Toyota prints more than one figure for a grade, the lowest and highest are shown. A dash means Toyota lists no figure.", "table": {"head": ["Grade", "Powertrain", "4x2", "4x4"], "rows": [["SR", "i-FORCE", "8,300 lb", "8,300 lb", 1], ["Limited", "i-FORCE", "11,230 to 11,400 lb", "10,970 to 11,120 lb", 1], ["Platinum", "i-FORCE", "11,180 to 11,310 lb", "10,890 to 11,050 lb", 1], ["1794 Edition", "i-FORCE", "11,290 to 11,380 lb", "10,890 to 11,050 lb", 1], ["Limited", "i-FORCE MAX hybrid", "11,350 to 11,450 lb", "11,040 to 11,170 lb", 1], ["Platinum", "i-FORCE MAX hybrid", "11,290 to 11,380 lb", "10,960 to 11,020 lb", 1], ["1794 Edition", "i-FORCE MAX hybrid", "11,290 to 11,380 lb", "10,960 to 11,020 lb", 1], ["TRD Pro", "i-FORCE MAX hybrid", "—", "11,175 lb", 1], ["Capstone", "i-FORCE MAX hybrid", "—", "10,340 lb", 1]]}, "notes": ["Toyota attaches a footnote to its towing figures. Read the towing section of the owner's manual for the equipment and loading conditions behind them."]}], "check": ["Find your grade, cab, bed, powertrain and drivetrain on the window sticker, then read the matching row.", "Read the labels on the driver's door jamb. The trailer you can pull also depends on your truck's gross combined weight rating, minus the truck, passengers and cargo.", "Check the tongue weight limit in your owner's manual before choosing a hitch or a ball mount.", "Your owner's manual and the labels on your own vehicle override this page."], "related": ["hitches", "tonneau-covers", "bed-racks"], "sources": [["Toyota, 2024 Tundra eBrochure, specifications table", "https://www.toyota.com/content/dam/toyota/brochures/pdf/2024/tundra_ebrochure.pdf"]], "reviewed": "2026-11-21"}$s$::jsonb, 'published', DATE '2026-11-23', TIMESTAMPTZ '2026-11-23 10:00:00+06', 'model', '')
